#include <array>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

std::string desc3_to_meshio(int d) {
    static const std::unordered_map<int, std::string> m = {
        {2, "vertex"},        {3, "line"},    {4, "line3"},    {5, "triangle"},
        {6, "triangle6"},     {7, "quad"},    {8, "quad8"},    {10, "tetra"},
        {11, "tetra10"},      {12, "wedge"},  {13, "wedge15"}, {15, "hexahedron"},
        {16, "hexahedron20"}, {17, "pyramid"}};
    auto it = m.find(d);
    return it == m.end() ? std::string() : it->second;
}

// meshio type -> (desc1, desc2, desc3)
bool meshio_to_desc(const std::string& rT, std::array<int, 3>& rOut) {
    static const std::unordered_map<std::string, std::array<int, 3>> m = {
        {"vertex", {1, 1, 2}},           {"line", {2, 2, 3}},       {"line3", {2, 3, 4}},
        {"triangle", {3, 7, 5}},         {"triangle6", {3, 7, 6}},  {"quad", {4, 202, 7}},
        {"quad8", {4, 303, 8}},          {"tetra", {5, 4, 10}},     {"tetra10", {5, 15, 11}},
        {"wedge", {6, 207, 12}},         {"wedge15", {6, 307, 13}}, {"hexahedron", {7, 2202, 15}},
        {"hexahedron20", {7, 3303, 16}}, {"pyramid", {8, 4202, 17}}};
    auto it = m.find(rT);
    if (it == m.end())
        return false;
    rOut = it->second;
    return true;
}

bool contains(const std::string& rHay, const char* pNeedle) {
    return rHay.find(pNeedle) != std::string::npos;
}

long long leading_int(const std::string& rLine) {
    std::istringstream iss(rLine);
    long long v = 0;
    iss >> v;
    return v;
}

}  // namespace

Mesh read_flux(const std::string& rPath) {
    std::ifstream in(rPath, std::ios::binary);
    if (!in)
        throw ReadError("Could not open file: " + rPath);
    std::vector<std::string> lines;
    std::string line;
    while (std::getline(in, line))
        lines.push_back(line);

    long long dim = 0, nel = 0, nnod = 0;
    std::size_t di = lines.size(), ci = lines.size();
    for (std::size_t i = 0; i < lines.size(); ++i) {
        const std::string& L = lines[i];
        if (contains(L, "NOMBRE DE DIMENSIONS"))
            dim = leading_int(L);
        else if (contains(L, "D'ELEMENTS") && !contains(L, "VOLUMIQUES") &&
                 !contains(L, "SURFACIQUES") && !contains(L, "LINEIQUES") &&
                 !contains(L, "PONCTUELS") && !contains(L, "MACRO"))
            nel = leading_int(L);
        else if (contains(L, "NOMBRE DE POINTS") && !contains(L, "INTEGRATION"))
            nnod = leading_int(L);
        else if (contains(L, "DESCRIPTEUR DE TOPOLOGIE"))
            di = i;
        else if (contains(L, "COORDONNEES DES NOEUDS"))
            ci = i;
    }
    if (di >= lines.size() || ci >= lines.size())
        throw ReadError("pf3: missing element/coordinate section");

    // element tokens
    std::vector<std::string> etok;
    for (std::size_t i = di + 1; i < ci; ++i) {
        std::istringstream iss(lines[i]);
        std::string w;
        while (iss >> w)
            etok.push_back(w);
    }

    struct Group {
        std::string mType;
        std::vector<std::vector<std::int64_t>> mRows;
        std::vector<std::int64_t> mRef;
    };
    std::vector<Group> groups;
    std::unordered_map<std::string, std::size_t> gindex;
    std::size_t pos = 0;
    for (long long e = 0; e < nel; ++e) {
        if (pos + 12 > etok.size())
            throw ReadError("pf3: truncated element header");
        long long ref = std::strtoll(etok[pos + 3].c_str(), nullptr, 10);
        int desc3 = std::atoi(etok[pos + 6].c_str());
        int lnn = std::atoi(etok[pos + 7].c_str());
        pos += 12;
        std::string mtype = desc3_to_meshio(desc3);
        if (mtype.empty())
            throw ReadError("pf3: unknown element descriptor");
        std::vector<std::int64_t> nodes(lnn);
        for (int j = 0; j < lnn; ++j)
            nodes[j] = std::strtoll(etok[pos + j].c_str(), nullptr, 10) - 1;
        pos += lnn;
        auto it = gindex.find(mtype);
        if (it == gindex.end()) {
            gindex[mtype] = groups.size();
            groups.push_back({mtype, {}, {}});
            it = gindex.find(mtype);
        }
        groups[it->second].mRows.push_back(std::move(nodes));
        groups[it->second].mRef.push_back(ref);
    }

    // coordinate tokens
    std::vector<std::string> ctok;
    for (std::size_t i = ci + 1; i < lines.size(); ++i) {
        std::istringstream iss(lines[i]);
        std::string w;
        while (iss >> w)
            ctok.push_back(w);
    }
    Mesh mesh;
    NDArray pts(DType::Float64,
                {static_cast<std::size_t>(nnod), static_cast<std::size_t>(dim)});
    std::size_t cp = 0;
    for (long long i = 0; i < nnod; ++i) {
        ++cp;  // node index
        for (long long j = 0; j < dim; ++j)
            pts.As<double>()[i * dim + j] = std::strtod(ctok[cp++].c_str(), nullptr);
    }
    mesh.AssignPoints(std::move(pts));

    std::vector<NDArray> refs;
    for (auto& g : groups) {
        std::size_t ne = g.mRows.size();
        std::size_t k = ne ? g.mRows[0].size() : 0;
        NDArray data(DType::Int64, {ne, k});
        for (std::size_t r = 0; r < ne; ++r)
            for (std::size_t j = 0; j < k; ++j)
                data.As<std::int64_t>()[r * k + j] = g.mRows[r][j];
        mesh.AddCellBlock(g.mType, std::move(data));
        NDArray rf(DType::Int64, {ne});
        for (std::size_t r = 0; r < ne; ++r)
            rf.As<std::int64_t>()[r] = g.mRef[r];
        refs.push_back(std::move(rf));
    }
    if (!refs.empty())
        mesh.AddCellData("pf3:ref", std::move(refs));
    return mesh;
}

void write_flux(const std::string& rPath, const Mesh& rMesh) {
    std::ofstream f(rPath, std::ios::binary);
    if (!f)
        throw WriteError("Could not open file for writing: " + rPath);

    const int dim = static_cast<int>(rMesh.PointDim());
    long long counts[4] = {0, 0, 0, 0};  // by topological dim
    std::vector<std::size_t> blocks;
    for (std::size_t k = 0; k < rMesh.NumCellBlocks(); ++k) {
        const auto cb = rMesh.Cells(k);
        std::array<int, 3> d;
        if (!meshio_to_desc(cb.Type(), d))
            throw WriteError("pf3: unsupported cell type " + cb.Type());
        auto it = topological_dimension().find(cb.Type());
        int td = it == topological_dimension().end() ? 3 : it->second;
        counts[td] += static_cast<long long>(cb.NumCells());
        blocks.push_back(k);
    }
    long long nel = 0;
    for (auto k : blocks)
        nel += static_cast<long long>(rMesh.Cells(k).NumCells());

    const bool has_ref = rMesh.HasCellData("pf3:ref");

    char buf[128];
    f << detail::provenance_render_lines(detail::SlotTier::Block, " ");
    auto hdr = [&](long long v, const char* label) {
        std::snprintf(buf, sizeof(buf), "%8lld           %s\n", v, label);
        f << buf;
    };
    hdr(dim, "NOMBRE DE DIMENSIONS DU DECOUPAGE");
    hdr(nel, "NOMBRE  D'ELEMENTS");
    hdr(counts[3], "NOMBRE  D'ELEMENTS VOLUMIQUES");
    hdr(counts[2], "NOMBRE  D'ELEMENTS SURFACIQUES");
    hdr(counts[1], "NOMBRE  D'ELEMENTS LINEIQUES");
    hdr(counts[0], "NOMBRE  D'ELEMENTS PONCTUELS");
    hdr(0, "NOMBRE DE MACRO-ELEMENTS");
    hdr(static_cast<long long>(rMesh.NumPoints()), "NOMBRE DE POINTS");
    hdr(1, "NOMBRE DE REGIONS");
    hdr(0, "NOMBRE DE REGIONS VOLUMIQUES");
    hdr(0, "NOMBRE DE REGIONS SURFACIQUES");
    hdr(0, "NOMBRE DE REGIONS LINEIQUES");
    hdr(0, "NOMBRE DE REGIONS PONCTUELLES");
    hdr(0, "NOMBRE DE REGIONS MACRO-ELEMENTAIRES");
    hdr(20, "NOMBRE DE NOEUDS DANS 1 ELEMENT (MAX)");
    hdr(20, "NOMBRE DE POINTS D'INTEGRATION / ELEMENT (MAX)");
    f << " NOMS DES REGIONS\n";
    f << " DESCRIPTEUR DE TOPOLOGIE DES ELEMENTS\n";

    long long eid = 0;
    for (auto k : blocks) {
        const auto cb = rMesh.Cells(k);
        std::array<int, 3> d;
        meshio_to_desc(cb.Type(), d);
        const NDArray& conn = cb.Conn();
        int lnn = static_cast<int>(detail::cols(conn));
        const NDArray* ref = (has_ref && k < rMesh.CellDataNumBlocks("pf3:ref"))
                                 ? &rMesh.CellData("pf3:ref", k)
                                 : nullptr;
        for (std::size_t r = 0; r < cb.NumCells(); ++r) {
            ++eid;
            long long rv = ref ? detail::read_int(*ref, r) : 0;
            std::snprintf(buf, sizeof(buf), "%8lld%8d%8d%8lld%8d%8d%8d%8d%8d%8d%8d%8d\n", eid, d[0],
                          d[1], rv, lnn, 0, d[2], lnn, 0, 0, 0, 0);
            f << buf;
            for (int j = 0; j < lnn; ++j) {
                std::snprintf(buf, sizeof(buf), "%8lld",
                              static_cast<long long>(detail::read_int(conn, r * lnn + j) + 1));
                f << buf;
            }
            f << "\n";
        }
    }

    f << " COORDONNEES DES NOEUDS\n";
    const NDArray& points = rMesh.Points();
    for (std::size_t i = 0; i < rMesh.NumPoints(); ++i) {
        std::snprintf(buf, sizeof(buf), "%8zu", i + 1);
        f << buf;
        for (int j = 0; j < dim; ++j) {
            std::snprintf(buf, sizeof(buf), " %.16g", detail::read_double(points, i * dim + j));
            f << buf;
        }
        f << "\n";
    }
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/formats/flux.cpp =====
// ===== begin src/cpp/src/formats/freefem.cpp =====
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

// Next non-blank line's whitespace tokens.
bool next_tokens(std::istream& rIn, std::vector<std::string>& rOut) {
    std::string line;
    while (std::getline(rIn, line)) {
        std::istringstream iss(line);
        std::string t;
        rOut.clear();
        while (iss >> t)
            rOut.push_back(t);
        if (!rOut.empty())
            return true;
    }
    return false;
}

}  // namespace

Mesh read_freefem(const std::string& rPath) {
    std::ifstream in(rPath, std::ios::binary);
    if (!in)
        throw ReadError("Could not open file: " + rPath);

    std::vector<std::string> tok;
    if (!next_tokens(in, tok) || tok.size() != 3)
        throw ReadError("FreeFem: expected a 3-integer header");
    const std::int64_t nver = std::strtoll(tok[0].c_str(), nullptr, 10);
    const std::int64_t n1 = std::strtoll(tok[1].c_str(), nullptr, 10);
    const std::int64_t n2 = std::strtoll(tok[2].c_str(), nullptr, 10);

    if (!next_tokens(in, tok))
        throw ReadError("FreeFem: missing vertices");
    const int dim = static_cast<int>(tok.size()) - 1;
    if (dim != 2 && dim != 3)
        throw ReadError("FreeFem: bad vertex dimension");

    Mesh mesh;
    NDArray pts(DType::Float64, {static_cast<std::size_t>(nver), static_cast<std::size_t>(dim)});
    NDArray pref(DType::Int64, {static_cast<std::size_t>(nver)});
    for (std::int64_t i = 0; i < nver; ++i) {
        if (i > 0 && !next_tokens(in, tok))
            throw ReadError("FreeFem: truncated vertices");
        for (int c = 0; c < dim; ++c)
            pts.As<double>()[i * dim + c] = std::strtod(tok[c].c_str(), nullptr);
        pref.As<std::int64_t>()[i] = std::strtoll(tok[dim].c_str(), nullptr, 10);
    }
    mesh.AssignPoints(std::move(pts));
    mesh.AddPointData("freefem:ref", std::move(pref));

    const char* t1 = dim == 2 ? "triangle" : "tetra";
    const int lnv1 = dim == 2 ? 3 : 4;
    const char* t2 = dim == 2 ? "line" : "triangle";
    const int lnv2 = dim == 2 ? 2 : 3;

    std::vector<NDArray> cell_refs;
    auto read_block = [&](std::int64_t n, const char* type, int lnv) {
        if (n <= 0)
            return;
        NDArray data(DType::Int64, {static_cast<std::size_t>(n), static_cast<std::size_t>(lnv)});
        NDArray ref(DType::Int64, {static_cast<std::size_t>(n)});
        for (std::int64_t k = 0; k < n; ++k) {
            if (!next_tokens(in, tok))
                throw ReadError("FreeFem: truncated elements");
            for (int j = 0; j < lnv; ++j)
                data.As<std::int64_t>()[k * lnv + j] =
                    std::strtoll(tok[j].c_str(), nullptr, 10) - 1;
            ref.As<std::int64_t>()[k] = std::strtoll(tok[lnv].c_str(), nullptr, 10);
        }
        mesh.AddCellBlock(type, std::move(data));
        cell_refs.push_back(std::move(ref));
    };
    read_block(n1, t1, lnv1);
    read_block(n2, t2, lnv2);
    if (!cell_refs.empty())
        mesh.AddCellData("freefem:ref", std::move(cell_refs));

    return mesh;
}

void write_freefem(const std::string& rPath, const Mesh& rMesh) {
    const int dim = static_cast<int>(rMesh.PointDim());
    if (dim != 2 && dim != 3)
        throw WriteError("FreeFem: can only write 2D/3D meshes");

    const std::string t1 = dim == 2 ? "triangle" : "tetra";
    const std::string t2 = dim == 2 ? "line" : "triangle";

    // Reject unsupported cell types so the shim falls back to Python (which
    // warns and skips). This keeps behaviour identical to the reference impl.
    for (const auto cb : rMesh.CellRange())
        if (cb.Type() != t1 && cb.Type() != t2)
            throw WriteError("FreeFem: unsupported cell type " + cb.Type());

    const bool has_ref = rMesh.HasCellData("freefem:ref");

    struct Row {
        Mesh::CellView mCb;
        const NDArray* mRef;
    };
    std::vector<Row> b1, b2;
    for (std::size_t i = 0; i < rMesh.NumCellBlocks(); ++i) {
        const NDArray* ref = (has_ref && i < rMesh.CellDataNumBlocks("freefem:ref"))
                                 ? &rMesh.CellData("freefem:ref", i)
                                 : nullptr;
        if (rMesh.Cells(i).Type() == t1)
            b1.push_back({rMesh.Cells(i), ref});
        else
            b2.push_back({rMesh.Cells(i), ref});
    }
    auto count = [](const std::vector<Row>& b) {
        std::size_t n = 0;
        for (const auto& r : b)
            n += r.mCb.NumCells();
        return n;
    };

    std::ofstream f(rPath, std::ios::binary);
    if (!f)
        throw WriteError("Could not open file for writing: " + rPath);

    const std::size_t nver = rMesh.NumPoints();
    f << nver << " " << count(b1) << " " << count(b2) << "\n";

    const NDArray* pref = rMesh.HasPointData("freefem:ref") ? &rMesh.PointData("freefem:ref")
                                                            : nullptr;

    const NDArray& points = rMesh.Points();
    char buf[32];
    for (std::size_t i = 0; i < nver; ++i) {
        for (int c = 0; c < dim; ++c) {
            std::snprintf(buf, sizeof(buf), "%.16e", detail::read_double(points, i * dim + c));
            f << buf << " ";
        }
        f << (pref ? detail::read_int(*pref, i) : 0) << "\n";
    }
    auto write_block = [&](const std::vector<Row>& b, int lnv) {
        for (const auto& r : b) {
            std::size_t n = r.mCb.NumCells();
            const NDArray& conn = r.mCb.Conn();
            std::size_t k = detail::cols(conn);
            for (std::size_t rr = 0; rr < n; ++rr) {
                for (int j = 0; j < lnv && static_cast<std::size_t>(j) < k; ++j)
                    f << (detail::read_int(conn, rr * k + j) + 1) << " ";
                f << (r.mRef ? detail::read_int(*r.mRef, rr) : 0) << "\n";
            }
        }
    };
    write_block(b1, dim == 2 ? 3 : 4);
    write_block(b2, dim == 2 ? 2 : 3);
}

}  // namespace meshioplusplus
