// ===== begin src/cpp/src/formats/svg.cpp =====
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <optional>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

// Format a single double with a printf-style spec (spec without leading '%',
// e.g. ".3f"), mirroring the Python reference's `format(x, float_fmt)`.
std::string svg_fmt_num(double value, const std::string& rSpec) {
    char buf[64];
    std::snprintf(buf, sizeof(buf), ("%" + rSpec).c_str(), value);
    return buf;
}

// SVG's colour vocabulary. Lowercase hex, as Python's "%02x" also produces.
std::string svg_color_hex(detail::Rgb c) {
    char buf[16];
    std::snprintf(buf, sizeof(buf), "#%02x%02x%02x", static_cast<int>(c.mR), static_cast<int>(c.mG),
                  static_cast<int>(c.mB));
    return buf;
}

// The extra viewBox width a colorbar occupies, as a multiple of the drawing's
// width. Only the viewBox grows: the scaling factor, the stroke width and every
// mesh coordinate are computed from the unmodified width.
constexpr double kSvgColorbarGap = 0.08;
constexpr double kSvgColorbarWidth = 0.06;
constexpr double kSvgColorbarLabels = 0.30;
constexpr std::size_t kSvgColorbarSegments = 32;

// The colorbar: a vertical gradient to the right of the drawing plus min/max
// labels. <rect>, not <path>, because the document-level `path {...}` rule
// would otherwise stroke every swatch. Emitted after the mesh so the painter
// ordering (and a d-attribute-only reading of the output) is undisturbed.
void svg_append_colorbar(std::ostream& rOs, const detail::FaceColors& rColors, double MinX,
                         double MinY, double Width, double Height, const std::string& rFloatFmt) {
    const double x0 = MinX + Width + Width * kSvgColorbarGap;
    const double bar_w = Width * kSvgColorbarWidth;
    for (std::size_t i = 0; i < kSvgColorbarSegments; ++i) {
        const double y0 =
            MinY + Height * (static_cast<double>(i) / static_cast<double>(kSvgColorbarSegments));
        const double seg_h = Height / static_cast<double>(kSvgColorbarSegments);
        // y grows downward in SVG, so the FIRST segment is the top one and
        // must carry the HIGH end of the range.
        const detail::Rgb c = detail::colormap_lookup(
            rColors.mpTable, static_cast<double>(kSvgColorbarSegments - 1 - i) /
                                 static_cast<double>(kSvgColorbarSegments - 1));
        rOs << "<rect x=\"" << svg_fmt_num(x0, rFloatFmt) << "\" y=\"" << svg_fmt_num(y0, rFloatFmt)
            << "\" width=\"" << svg_fmt_num(bar_w, rFloatFmt) << "\" height=\""
            << svg_fmt_num(seg_h, rFloatFmt) << "\" fill=\"" << svg_color_hex(c) << "\" />";
    }
    const double label_x = x0 + bar_w + Width * 0.02;
    const double font_size = Width * 0.04;
    rOs << "<text x=\"" << svg_fmt_num(label_x, rFloatFmt) << "\" y=\""
        << svg_fmt_num(MinY + font_size, rFloatFmt) << "\" font-size=\""
        << svg_fmt_num(font_size, rFloatFmt) << "\">" << svg_fmt_num(rColors.mVMax, rFloatFmt)
        << "</text>";
    rOs << "<text x=\"" << svg_fmt_num(label_x, rFloatFmt) << "\" y=\""
        << svg_fmt_num(MinY + Height, rFloatFmt) << "\" font-size=\""
        << svg_fmt_num(font_size, rFloatFmt) << "\">" << svg_fmt_num(rColors.mVMin, rFloatFmt)
        << "</text>";
}

// 3D rendering path: project the (already skin-extracted) surface mesh with
// the orthographic camera and emit its faces back-to-front. Replicates the
// flat path's bbox -> y-flip -> image_width scaling -> <path> emission, but
// over the sorted projected faces.
void svg_proj_write(const std::string& rPath, const Mesh& rSourceMesh, const Mesh& rDrawMesh,
                    const std::string& rFloatFmt, const std::optional<std::string>& rStrokeWidth,
                    const std::optional<double>& rImageWidth, const std::string& rFill,
                    const std::string& rStroke, double azimuth, double elevation, double roll,
                    const detail::ColorSpec& rColorSpec, const std::string& rNanColor) {
    detail::ProjectedSurface ps = detail::project_surface(rDrawMesh, azimuth, elevation, roll);
    const detail::FaceColors colors = detail::resolve_face_colors(
        rColorSpec, rSourceMesh, rDrawMesh, detail::color_faces_from_projection(ps.mFaces));
    std::vector<double>& x = ps.mX;
    std::vector<double>& y = ps.mY;
    const std::size_t num_points = x.size();

    double min_x = 0.0, max_x = 0.0, min_y = 0.0, max_y = 0.0;
    if (num_points > 0) {
        min_x = max_x = x[0];
        min_y = max_y = y[0];
        for (std::size_t i = 1; i < num_points; ++i) {
            min_x = std::min(min_x, x[i]);
            max_x = std::max(max_x, x[i]);
            min_y = std::min(min_y, y[i]);
            max_y = std::max(max_y, y[i]);
        }
    }

    // Flip y (projected math convention y-up -> SVG screen convention y-down).
    for (std::size_t i = 0; i < num_points; ++i)
        y[i] = max_y + min_y - y[i];

    double width = max_x - min_x;
    double height = max_y - min_y;

    if (rImageWidth.has_value() && width != 0.0) {
        const double scaling_factor = *rImageWidth / width;
        min_x *= scaling_factor;
        min_y *= scaling_factor;
        width *= scaling_factor;
        height *= scaling_factor;
        for (std::size_t i = 0; i < num_points; ++i) {
            x[i] *= scaling_factor;
            y[i] *= scaling_factor;
        }
    }

    std::string stroke_width;
    if (rStrokeWidth.has_value()) {
        stroke_width = *rStrokeWidth;
    } else {
        char buf[64];
        std::snprintf(buf, sizeof(buf), "%g", width / 100.0);
        stroke_width = buf;
    }

    std::ofstream os(rPath, std::ios::binary);
    if (!os)
        throw WriteError("Could not open file for writing: " + rPath);

    const bool colorbar = colors.mActive && rColorSpec.mColorbar;
    const double view_width =
        colorbar ? width * (1.0 + kSvgColorbarGap + kSvgColorbarWidth + kSvgColorbarLabels) : width;

    os << "<svg xmlns=\"http://www.w3.org/2000/svg\" version=\"1.1\" viewBox=\""
       << svg_fmt_num(min_x, rFloatFmt) << ' ' << svg_fmt_num(min_y, rFloatFmt) << ' '
       << svg_fmt_num(view_width, rFloatFmt) << ' ' << svg_fmt_num(height, rFloatFmt) << "\">";

    os << "<style>path {fill: " << rFill << "; stroke: " << rStroke
       << "; stroke-width: " << stroke_width << "; stroke-linejoin:bevel}</style>";

    for (std::size_t f = 0; f < ps.mFaces.size(); ++f) {
        const detail::ProjectedFace& face = ps.mFaces[f];
        std::string d;
        for (std::uint8_t k = 0; k < face.mNumNodes; ++k) {
            const std::int64_t p = face.mNodes[k];
            d += (k == 0) ? "M " : "L ";
            d += svg_fmt_num(x[static_cast<std::size_t>(p)], rFloatFmt);
            d += ' ';
            d += svg_fmt_num(y[static_cast<std::size_t>(p)], rFloatFmt);
        }
        if (!face.mIsLine)
            d += "Z";
        // A per-path fill attribute overrides the document-level rule; without
        // coloring no attribute is emitted and the output is unchanged.
        if (colors.mActive && !face.mIsLine) {
            const std::optional<detail::Rgb> c = colors.Color(f);
            os << "<path d=\"" << d << "\" fill=\""
               << (c.has_value() ? svg_color_hex(*c) : rNanColor) << "\" />";
        } else {
            os << "<path d=\"" << d << "\" />";
        }
    }

    if (colorbar)
        svg_append_colorbar(os, colors, min_x, min_y, width, height, rFloatFmt);

    os << "</svg>";
}

}  // namespace

void write_svg(const std::string& rPath, const Mesh& rMesh, const std::string& rFloatFmt,
               const std::optional<std::string>& rStrokeWidth,
               const std::optional<double>& rImageWidth, const std::string& rFill,
               const std::string& rStroke, double azimuth, double elevation, double roll,
               const std::string& rColorBy, const std::optional<int>& rComponent,
               const std::string& rCmap, const std::optional<double>& rVMin,
               const std::optional<double>& rVMax, const std::string& rNanColor, bool Colorbar) {
    const NDArray& points = rMesh.Points();
    const std::size_t num_points = rMesh.NumPoints();
    const std::size_t dim = rMesh.PointDim();

    // A genuinely non-flat 3D mesh takes the projected-rendering path (skin
    // extraction for volume cells + orthographic camera); a flat one (every
    // z ~ 0) keeps the classic 2D path below, byte-identical to before.
    detail::ColorSpec spec;
    spec.mColorBy = rColorBy;
    spec.mComponent = rComponent;
    spec.mCmap = rCmap;
    spec.mVMin = rVMin;
    spec.mVMax = rVMax;
    spec.mColorbar = Colorbar;

    if (dim == 3) {
        for (std::size_t i = 0; i < num_points; ++i) {
            if (std::fabs(detail::read_double(points, i * dim + 2)) > 1.0e-14) {
                if (has_skinnable_cells(rMesh)) {
                    // Colouring by cell data needs to know which input cell
                    // each skin facet came from; that costs an extra Int64
                    // array, so only ask for it when it will actually be read.
                    const bool need_parents = spec.Active() && rMesh.HasCellData(rColorBy);
                    const Mesh skin =
                        detail::surface_extract(rMesh, /*forceFaceMode=*/true,
                                                /*linearize=*/true, need_parents, "extract_skin");
                    svg_proj_write(rPath, rMesh, skin, rFloatFmt, rStrokeWidth, rImageWidth, rFill,
                                   rStroke, azimuth, elevation, roll, spec, rNanColor);
                } else {
                    svg_proj_write(rPath, rMesh, rMesh, rFloatFmt, rStrokeWidth, rImageWidth, rFill,
                                   rStroke, azimuth, elevation, roll, spec, rNanColor);
                }
                return;
            }
        }
    }

    // Copy the first two coordinate columns.
    std::vector<double> x(num_points), y(num_points);
    for (std::size_t i = 0; i < num_points; ++i) {
        x[i] = (0 < dim) ? detail::read_double(points, i * dim + 0) : 0.0;
        y[i] = (1 < dim) ? detail::read_double(points, i * dim + 1) : 0.0;
    }

    double min_x = 0.0, max_x = 0.0, min_y = 0.0, max_y = 0.0;
    if (num_points > 0) {
        min_x = max_x = x[0];
        min_y = max_y = y[0];
        for (std::size_t i = 1; i < num_points; ++i) {
            min_x = std::min(min_x, x[i]);
            max_x = std::max(max_x, x[i]);
            min_y = std::min(min_y, y[i]);
            max_y = std::max(max_y, y[i]);
        }
    }

    // Flip y (mesh math convention y-up -> SVG screen convention y-down).
    for (std::size_t i = 0; i < num_points; ++i)
        y[i] = max_y + min_y - y[i];

    double width = max_x - min_x;
    double height = max_y - min_y;

    if (rImageWidth.has_value() && width != 0.0) {
        const double scaling_factor = *rImageWidth / width;
        min_x *= scaling_factor;
        min_y *= scaling_factor;
        width *= scaling_factor;
        height *= scaling_factor;
        for (std::size_t i = 0; i < num_points; ++i) {
            x[i] *= scaling_factor;
            y[i] *= scaling_factor;
        }
    }

    std::string stroke_width;
    if (rStrokeWidth.has_value()) {
        stroke_width = *rStrokeWidth;
    } else {
        char buf[64];
        std::snprintf(buf, sizeof(buf), "%g", width / 100.0);
        stroke_width = buf;
    }

    std::ofstream os(rPath, std::ios::binary);
    if (!os)
        throw WriteError("Could not open file for writing: " + rPath);

    // On the flat path the drawn mesh IS the source mesh, so a face's cell
    // index needs no provenance indirection.
    const detail::FaceColors colors =
        detail::resolve_face_colors(spec, rMesh, rMesh, detail::color_faces_flat(rMesh));
    const bool colorbar = colors.mActive && spec.mColorbar;
    const double view_width =
        colorbar ? width * (1.0 + kSvgColorbarGap + kSvgColorbarWidth + kSvgColorbarLabels) : width;

    // viewBox: "min_x min_y width height", each float_fmt-formatted.
    os << "<svg xmlns=\"http://www.w3.org/2000/svg\" version=\"1.1\" viewBox=\""
       << svg_fmt_num(min_x, rFloatFmt) << ' ' << svg_fmt_num(min_y, rFloatFmt) << ' '
       << svg_fmt_num(view_width, rFloatFmt) << ' ' << svg_fmt_num(height, rFloatFmt) << "\">";

    // Use path (not polygon): svgo rewrites polygons to paths but drops style.
    os << "<style>path {fill: " << rFill << "; stroke: " << rStroke
       << "; stroke-width: " << stroke_width << "; stroke-linejoin:bevel}</style>";

    std::size_t face_index = 0;
    for (const auto cb : rMesh.CellRange()) {
        const std::string& type = cb.Type();
        if (type != "line" && type != "triangle" && type != "quad")
            continue;

        const NDArray& conn = cb.Conn();
        const std::size_t ncols = detail::cols(conn);
        const std::size_t n = cb.NumCells();
        for (std::size_t r = 0; r < n; ++r) {
            std::string d;
            for (std::size_t k = 0; k < ncols; ++k) {
                const std::int64_t p = detail::read_int(conn, r * ncols + k);
                // "M x y" for the first vertex, "L x y" for the rest — no
                // separating space before the command letter (matches the
                // Python reference's concatenated format strings).
                d += (k == 0) ? "M " : "L ";
                d += svg_fmt_num(x[static_cast<std::size_t>(p)], rFloatFmt);
                d += ' ';
                d += svg_fmt_num(y[static_cast<std::size_t>(p)], rFloatFmt);
            }
            // triangle/quad are closed; line stays open.
            if (type != "line")
                d += "Z";
            const std::size_t f = face_index++;
            if (colors.mActive && type != "line") {
                const std::optional<detail::Rgb> c = colors.Color(f);
                os << "<path d=\"" << d << "\" fill=\""
                   << (c.has_value() ? svg_color_hex(*c) : rNanColor) << "\" />";
            } else {
                os << "<path d=\"" << d << "\" />";
            }
        }
    }

    if (colorbar)
        svg_append_colorbar(os, colors, min_x, min_y, width, height, rFloatFmt);

    os << "</svg>";
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/formats/svg.cpp =====
// ===== begin src/cpp/src/formats/tecplot.cpp =====
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <map>
#include <set>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

std::string tecplot_upper(std::string s) {
    for (auto& c : s)
        c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    return s;
}
std::string tecplot_strip(const std::string& rS) {
    std::size_t b = rS.find_first_not_of(" \t\r\n");
    if (b == std::string::npos)
        return "";
    std::size_t e = rS.find_last_not_of(" \t\r\n");
    return rS.substr(b, e - b + 1);
}
std::vector<std::string> tecplot_tokens(const std::string& rS) {
    std::vector<std::string> out;
    std::istringstream iss(rS);
    std::string t;
    while (iss >> t)
        out.push_back(t);
    return out;
}
bool is_float_token(const std::string& rS) {
    if (rS.empty())
        return false;
    char* endp = nullptr;
    std::strtod(rS.c_str(), &endp);
    return endp == rS.c_str() + rS.size();
}

std::string tecplot_to_meshio(const std::string& rZ) {
    std::string u = tecplot_upper(rZ);
    if (u == "LINESEG" || u == "FELINESEG")
        return "line";
    if (u == "TRIANGLE" || u == "FETRIANGLE")
        return "triangle";
    if (u == "QUADRILATERAL" || u == "FEQUADRILATERAL")
        return "quad";
    if (u == "TETRAHEDRON" || u == "FETETRAHEDRON")
        return "tetra";
    if (u == "BRICK" || u == "FEBRICK")
        return "hexahedron";
    return "";
}
std::string meshio_to_tecplot(const std::string& rM) {
    if (rM == "line")
        return "FELINESEG";
    if (rM == "triangle")
        return "FETRIANGLE";
    if (rM == "quad")
        return "FEQUADRILATERAL";
    if (rM == "tetra")
        return "FETETRAHEDRON";
    if (rM == "pyramid" || rM == "wedge" || rM == "hexahedron")
        return "FEBRICK";
    return "";
}
const std::vector<int>& tecplot_order(const std::string& rM) {
    static const std::map<std::string, std::vector<int>> o = {
        {"line", {0, 1}},
        {"triangle", {0, 1, 2}},
        {"quad", {0, 1, 2, 3}},
        {"tetra", {0, 1, 2, 3}},
        {"pyramid", {0, 1, 2, 3, 4, 4, 4, 4}},
        {"wedge", {0, 1, 4, 3, 2, 2, 5, 5}},
        {"hexahedron", {0, 1, 2, 3, 4, 5, 6, 7}},
    };
    static const std::vector<int> empty;
    auto it = o.find(rM);
    return it == o.end() ? empty : it->second;
}

}  // namespace

Mesh read_tecplot(const std::string& rPath) {
    std::ifstream in(rPath);
    if (!in)
        throw ReadError("Could not open file: " + rPath);
    std::vector<std::string> lines;
    std::string l;
    while (std::getline(in, l)) {
        std::string s = tecplot_strip(l);
        if (s.empty() || s[0] == '#')
            continue;
        lines.push_back(s);
    }

    std::vector<std::string> variables;
    std::map<std::string, std::string> zone;
    std::string varloc;
    std::size_t i = 0, data_start = lines.size();
    for (; i < lines.size(); ++i) {
        std::string u = tecplot_upper(lines[i]);
        if (u.rfind("VARIABLES", 0) == 0) {
            std::string joined = lines[i];
            while (i + 1 < lines.size() && tecplot_strip(lines[i + 1])[0] == '"')
                joined += " " + lines[++i];
            std::string rhs = joined.substr(joined.find('=') + 1);
            // collect quoted names (or bare tokens)
            std::size_t p = 0;
            while (p < rhs.size()) {
                if (rhs[p] == '"') {
                    std::size_t q = rhs.find('"', p + 1);
                    variables.push_back(rhs.substr(p + 1, q - p - 1));
                    p = q + 1;
                } else if (std::isspace((unsigned char)rhs[p]) || rhs[p] == ',') {
                    ++p;
                } else {
                    std::size_t q = p;
                    while (q < rhs.size() && !std::isspace((unsigned char)rhs[q]) && rhs[q] != ',')
                        ++q;
                    variables.push_back(rhs.substr(p, q - p));
                    p = q;
                }
            }
        } else if (u.rfind("ZONE", 0) == 0) {
            std::string joined = lines[i];
            while (i + 1 < lines.size() && !is_float_token(tecplot_tokens(lines[i + 1])[0]))
                joined += " " + lines[++i];
            data_start = i + 1;
            // Extract VARLOCATION(...)
            std::string ju = joined;
            std::size_t vp = tecplot_upper(ju).find("VARLOCATION");
            if (vp != std::string::npos) {
                std::size_t p1 = ju.find('(', vp), p2 = ju.find(')', p1);
                varloc = ju.substr(p1, p2 - p1 + 1);
                varloc.erase(std::remove(varloc.begin(), varloc.end(), ' '), varloc.end());
                ju = ju.substr(0, vp) + ju.substr(p2 + 1);
            }
            // tokenize key/values (drop ZONE, replace ,/= with space)
            std::string body = ju.substr(4);
            for (auto& c : body)
                if (c == ',' || c == '=')
                    c = ' ';
            auto tk = tecplot_tokens(body);
            for (std::size_t k = 0; k + 1 < tk.size(); ++k) {
                std::string key = tecplot_upper(tk[k]);
                if (key == "NODES" || key == "N" || key == "ELEMENTS" || key == "E" ||
                    key == "DATAPACKING" || key == "ZONETYPE" || key == "F" || key == "ET" ||
                    key == "NV")
                    zone[key] = tk[k + 1];
            }
            break;
        }
    }
    if (variables.empty())
        throw ReadError("Tecplot: no VARIABLES");

    auto getz = [&](const char* a, const char* b) -> std::string {
        if (zone.count(a))
            return zone[a];
        if (zone.count(b))
            return zone[b];
        return "";
    };
    std::size_t num_nodes = std::stoull(getz("NODES", "N"));
    std::size_t num_cells = std::stoull(getz("ELEMENTS", "E"));
    std::string fmt, ztype;
    if (zone.count("F")) {
        fmt = tecplot_upper(zone["F"]);
        ztype = zone.count("ET") ? zone["ET"] : "";
    } else {
        fmt = "FE" + tecplot_upper(getz("DATAPACKING", ""));
        ztype = getz("ZONETYPE", "");
    }
    bool feblock = (fmt == "FEBLOCK");

    std::vector<int> cell_centered(variables.size(), 0);
    if (feblock) {
        if (zone.count("NV")) {
            int nv = std::stoi(zone["NV"]);
            for (std::size_t k = nv; k < variables.size(); ++k)
                cell_centered[k] = 1;
        } else if (!varloc.empty()) {
            std::string vc = varloc.substr(1, varloc.size() - 2);  // strip ()
            for (const auto& entry : [&] {
                     std::vector<std::string> es;
                     std::string cur;
                     for (char c : vc) {
                         if (c == ',') {
                             es.push_back(cur);
                             cur.clear();
                         } else
                             cur += c;
                     }
                     if (!cur.empty())
                         es.push_back(cur);
                     return es;
                 }()) {
                std::size_t eq = entry.find('=');
                if (eq == std::string::npos)
                    continue;
                std::string rng = entry.substr(0, eq), loc = tecplot_upper(entry.substr(eq + 1));
                if (loc != "CELLCENTERED")
                    continue;
                rng = rng.substr(1, rng.size() - 2);  // strip []
                std::size_t dash = rng.find('-');
                if (dash == std::string::npos) {
                    cell_centered[std::stoi(rng) - 1] = 1;
                } else {
                    int a = std::stoi(rng.substr(0, dash)), b = std::stoi(rng.substr(dash + 1));
                    for (int k = a; k <= b; ++k)
                        cell_centered[k - 1] = 1;
                }
            }
        }
    }

    // Read data values.
    std::vector<std::size_t> ndata(variables.size());
    std::size_t total = 0;
    for (std::size_t k = 0; k < variables.size(); ++k) {
        ndata[k] = cell_centered[k] ? num_cells : num_nodes;
        total += ndata[k];
    }
    std::size_t want = feblock ? total : num_nodes * variables.size();

    std::vector<double> flat;
    flat.reserve(want);
    std::size_t li = data_start;
    while (flat.size() < want && li < lines.size()) {
        for (const auto& t : tecplot_tokens(lines[li]))
            flat.push_back(std::strtod(t.c_str(), nullptr));
        ++li;
    }

    // Per-variable columns.
    std::vector<std::vector<double>> cols(variables.size());
    if (feblock) {
        std::size_t off = 0;
        for (std::size_t k = 0; k < variables.size(); ++k) {
            cols[k].assign(flat.begin() + off, flat.begin() + off + ndata[k]);
            off += ndata[k];
        }
    } else {
        std::size_t nv = variables.size();
        for (std::size_t k = 0; k < nv; ++k)
            cols[k].resize(num_nodes);
        for (std::size_t r = 0; r < num_nodes; ++r)
            for (std::size_t k = 0; k < nv; ++k)
                cols[k][r] = flat[r * nv + k];
    }

    // Cells.
    std::string mtype = tecplot_to_meshio(ztype);
    if (mtype.empty())
        throw ReadError("Tecplot: unsupported zone type " + ztype);
    std::size_t nn;
    if (mtype == "line")
        nn = 2;
    else if (mtype == "triangle")
        nn = 3;
    else if (mtype == "quad" || mtype == "tetra")
        nn = 4;
    else
        nn = 8;
    NDArray celldata(DType::Int64, {num_cells, nn});
    std::int64_t* cp = celldata.As<std::int64_t>();
    for (std::size_t c = 0; c < num_cells; ++c) {
        auto t = tecplot_tokens(lines.at(li++));
        for (std::size_t j = 0; j < nn; ++j)
            cp[c * nn + j] = std::strtoll(t[j].c_str(), nullptr, 10) - 1;
    }

    // Assemble.
    Mesh mesh;
    int xi = -1, yi = -1, zi = -1;
    for (std::size_t k = 0; k < variables.size(); ++k) {
        std::string v = tecplot_upper(variables[k]);
        if (v == "X")
            xi = (int)k;
        else if (v == "Y")
            yi = (int)k;
        else if (v == "Z")
            zi = (int)k;
    }
    std::size_t ndim = (zi >= 0) ? 3 : 2;
    NDArray pts(DType::Float64, {num_nodes, ndim});
    double* pp = pts.As<double>();
    for (std::size_t r = 0; r < num_nodes; ++r) {
        pp[r * ndim + 0] = cols[xi][r];
        pp[r * ndim + 1] = cols[yi][r];
        if (zi >= 0)
            pp[r * ndim + 2] = cols[zi][r];
    }
    mesh.AssignPoints(std::move(pts));
    for (std::size_t k = 0; k < variables.size(); ++k) {
        if ((int)k == xi || (int)k == yi || (int)k == zi)
            continue;
        NDArray arr(DType::Float64, {cols[k].size()});
        std::memcpy(arr.Data(), cols[k].data(), cols[k].size() * sizeof(double));
        if (cell_centered[k]) {
            std::vector<NDArray> blk;
            blk.push_back(std::move(arr));
            mesh.AddCellData(variables[k], std::move(blk));
        } else {
            mesh.AddPointData(variables[k], std::move(arr));
        }
    }
    mesh.AddCellBlock(mtype, std::move(celldata));
    return mesh;
}

void write_tecplot(const std::string& rPath, const Mesh& rMesh) {
    // Gather supported cell blocks; require a single unique type.
    std::vector<std::size_t> blocks;
    std::set<std::string> types;
    for (std::size_t i = 0; i < rMesh.NumCellBlocks(); ++i) {
        const auto cb = rMesh.Cells(i);
        if (!meshio_to_tecplot(cb.Type()).empty()) {
            blocks.push_back(i);
            types.insert(cb.Type());
        }
    }
    if (types.size() != 1)
        throw WriteError("C++ Tecplot writer supports a single cell type");
    std::string mtype = *types.begin();
    std::string ztype = meshio_to_tecplot(mtype);
    const std::vector<int>& order = tecplot_order(mtype);

    std::ofstream os(rPath);
    if (!os)
        throw WriteError("Could not open file for writing: " + rPath);

    const std::size_t dim = rMesh.PointDim();
    const std::size_t num_nodes = rMesh.NumPoints();
    std::size_t num_cells = 0;
    for (std::size_t b : blocks)
        num_cells += rMesh.Cells(b).NumCells();

    // Variables + data columns.
    const NDArray& points = rMesh.Points();
    std::vector<std::string> variables = {"X", "Y"};
    std::vector<std::vector<double>> data;
    auto push_point_col = [&](std::size_t comp) {
        std::vector<double> col(num_nodes);
        for (std::size_t r = 0; r < num_nodes; ++r)
            col[r] = detail::read_double(points, r * dim + comp);
        data.push_back(std::move(col));
    };
    push_point_col(0);
    push_point_col(1);
    int varrange0 = 3, varrange1 = 0;
    if (dim == 3) {
        variables.push_back("Z");
        push_point_col(2);
        varrange0 += 1;
    }

    for (const auto& k : rMesh.PointDataNames()) {
        std::string ku = tecplot_upper(k);
        if (ku == "X" || ku == "Y" || ku == "Z")
            continue;
        const NDArray& v = rMesh.PointData(k);
        std::size_t ncomp = v.Shape().size() >= 2 ? v.Shape()[1] : 1;
        for (std::size_t c = 0; c < ncomp; ++c) {
            variables.push_back(ncomp == 1 ? k : k + "_" + std::to_string(c));
            std::vector<double> col(num_nodes);
            for (std::size_t r = 0; r < num_nodes; ++r)
                col[r] = detail::read_double(v, r * ncomp + c);
            data.push_back(std::move(col));
            varrange0 += 1;
        }
    }
    bool have_cell_data = false;
    varrange1 = varrange0 - 1;
    for (const auto& k : rMesh.CellDataNames()) {
        std::string ku = tecplot_upper(k);
        if (ku == "X" || ku == "Y" || ku == "Z")
            continue;
        if (rMesh.CellDataNumBlocks(k) == 0)
            continue;
        // concatenate the (single-type) blocks
        const NDArray& first = rMesh.CellData(k, 0);
        std::size_t ncomp = first.Shape().size() >= 2 ? first.Shape()[1] : 1;
        for (std::size_t c = 0; c < ncomp; ++c) {
            variables.push_back(ncomp == 1 ? k : k + "_" + std::to_string(c));
            std::vector<double> col;
            for (std::size_t b : blocks) {
                const NDArray& vv = rMesh.CellData(k, b);
                for (std::size_t r = 0; r < vv.Shape()[0]; ++r)
                    col.push_back(detail::read_double(vv, r * ncomp + c));
            }
            data.push_back(std::move(col));
            varrange1 += 1;
            have_cell_data = true;
        }
    }

    os << "TITLE = \"" << detail::provenance_lines(detail::SlotTier::SingleLine)[0] << "\"\n";
    os << "VARIABLES = ";
    for (std::size_t k = 0; k < variables.size(); ++k)
        os << (k ? ", " : "") << "\"" << variables[k] << "\"";
    os << "\n";
    os << "ZONE NODES = " << num_nodes << ", ELEMENTS = " << num_cells << ",\n";
    os << "DATAPACKING = BLOCK, ZONETYPE = " << ztype;
    if (have_cell_data && varrange0 <= varrange1) {
        os << ",\n";
        std::string r = (varrange0 == varrange1)
                            ? std::to_string(varrange0)
                            : std::to_string(varrange0) + "-" + std::to_string(varrange1);
        os << "VARLOCATION = ([" << r << "] = CELLCENTERED)\n";
    } else {
        os << "\n";
    }

    char buf[40];
    for (const auto& col : data) {
        for (std::size_t i = 0; i < col.size(); ++i) {
            std::snprintf(buf, sizeof(buf), "%.17g", col[i]);
            os << buf << ((i + 1) % 20 == 0 || i + 1 == col.size() ? '\n' : ' ');
        }
        if (col.empty())
            os << "\n";
    }

    for (std::size_t b : blocks) {
        const auto cb = rMesh.Cells(b);
        const NDArray& conn = cb.Conn();
        std::size_t k = conn.Shape().size() >= 2 ? conn.Shape()[1] : 1;
        for (std::size_t r = 0; r < cb.NumCells(); ++r) {
            for (std::size_t j = 0; j < order.size(); ++j) {
                std::size_t src = static_cast<std::size_t>(order[j]);
                if (src >= k)
                    src = k - 1;
                os << (detail::read_int(conn, r * k + src) + 1)
                   << (j + 1 == order.size() ? '\n' : ' ');
            }
        }
    }
}

}  // namespace meshioplusplus
