#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

// A named list of per-block kept-cell lists (one output piece, pre-prune).
struct SplitGroup {
    std::string key;
    std::vector<std::vector<std::int64_t>> kept;  // per input block
};

// Ensure every group has one (possibly empty) kept list per input block.
void split_init_group(SplitGroup& rG, std::size_t nblocks) {
    rG.kept.assign(nblocks, {});
}

// Union-find over global cell indices (flood-fill for connected components).
std::int64_t split_uf_find(std::vector<std::int64_t>& rParent, std::int64_t x) {
    while (rParent[static_cast<std::size_t>(x)] != x) {
        rParent[static_cast<std::size_t>(x)] =
            rParent[static_cast<std::size_t>(rParent[static_cast<std::size_t>(x)])];
        x = rParent[static_cast<std::size_t>(x)];
    }
    return x;
}

void split_uf_union(std::vector<std::int64_t>& rParent, std::int64_t a, std::int64_t b) {
    std::int64_t ra = split_uf_find(rParent, a), rb = split_uf_find(rParent, b);
    if (ra != rb)
        rParent[static_cast<std::size_t>(std::max(ra, rb))] = std::min(ra, rb);
}

// Visit each node index of one cell (rectangular / polygon / polyhedron).
template <class F>
void split_visit_nodes(const Mesh::CellView& rCb, std::size_t c, F&& f) {
    if (rCb.IsPolyhedron()) {
        for (std::size_t face = 0; face < rCb.NumFaces(c); ++face) {
            auto fc = rCb.Face(c, face);
            for (std::size_t k = 0; k < fc.second; ++k)
                f(fc.first[k]);
        }
    } else if (rCb.IsRagged()) {
        for (std::size_t k = 0; k < rCb.RowSize(c); ++k)
            f(rCb.Row(c)[k]);
    } else {
        const NDArray& conn = rCb.Conn();
        const std::size_t npc = rCb.NodesPerCell();
        for (std::size_t k = 0; k < npc; ++k)
            f(detail::read_int(conn, c * npc + k));
    }
}

std::vector<SplitGroup> split_by_type(const Mesh& rMesh) {
    const std::size_t nblocks = rMesh.NumCellBlocks();
    std::vector<SplitGroup> groups;
    std::unordered_map<std::string, std::size_t> index;
    std::size_t b = 0;
    for (const auto cb : rMesh.CellRange()) {
        const std::string type(cb.Type());
        auto it = index.find(type);
        std::size_t gi;
        if (it == index.end()) {
            gi = groups.size();
            index[type] = gi;
            groups.push_back({});
            groups.back().key = type;
            split_init_group(groups.back(), nblocks);
        } else {
            gi = it->second;
        }
        std::vector<std::int64_t>& dst = groups[gi].kept[b];
        for (std::size_t c = 0; c < cb.NumCells(); ++c)
            dst.push_back(static_cast<std::int64_t>(c));
        ++b;
    }
    return groups;
}

std::vector<SplitGroup> split_by_component(const Mesh& rMesh) {
    const std::size_t nblocks = rMesh.NumCellBlocks();
    const std::size_t n = rMesh.NumPoints();

    // Global cell numbering (blocks concatenated in order).
    std::vector<std::size_t> block_base(nblocks + 1, 0);
    std::size_t bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        block_base[bi + 1] = block_base[bi] + cb.NumCells();
        ++bi;
    }
    const std::size_t total = block_base[nblocks];

    std::vector<std::int64_t> parent(total);
    for (std::size_t i = 0; i < total; ++i)
        parent[i] = static_cast<std::int64_t>(i);

    // Union cells that share a node (first cell per node as the anchor).
    std::vector<std::int64_t> node_first(n, -1);
    bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        for (std::size_t c = 0; c < cb.NumCells(); ++c) {
            const std::int64_t gc = static_cast<std::int64_t>(block_base[bi] + c);
            split_visit_nodes(cb, c, [&](std::int64_t node) {
                std::int64_t& first = node_first[static_cast<std::size_t>(node)];
                if (first < 0)
                    first = gc;
                else
                    split_uf_union(parent, first, gc);
            });
        }
        ++bi;
    }

    // Map component roots to piece indices in first-seen (ascending gc) order.
    std::vector<SplitGroup> groups;
    std::unordered_map<std::int64_t, std::size_t> root_index;
    std::vector<std::size_t> gc_to_group(total, 0);
    for (std::size_t gc = 0; gc < total; ++gc) {
        const std::int64_t root = split_uf_find(parent, static_cast<std::int64_t>(gc));
        auto it = root_index.find(root);
        std::size_t gi;
        if (it == root_index.end()) {
            gi = groups.size();
            root_index[root] = gi;
            groups.push_back({});
            groups.back().key = std::to_string(gi);
            split_init_group(groups.back(), nblocks);
        } else {
            gi = it->second;
        }
        gc_to_group[gc] = gi;
    }

    for (std::size_t b = 0; b < nblocks; ++b)
        for (std::size_t c = 0; c < block_base[b + 1] - block_base[b]; ++c)
            groups[gc_to_group[block_base[b] + c]].kept[b].push_back(static_cast<std::int64_t>(c));

    return groups;
}

// One piece per named Cell region. Unlike every other criterion, this is not a
// partition: a cell belonging to two regions appears in two pieces, and a cell
// in none appears in none -- each named region is processed independently, so
// "split by region" means exactly what it says rather than reinterpreting
// overlapping groups as a forced partition.
//
// Point/Side regions produce no piece: split's contract is whole submeshes,
// and there is no sound way to turn "these facets" or "these points" into one
// without first deciding which surrounding cells to pull in -- a policy
// decision this operation does not make silently.
std::vector<SplitGroup> split_by_region(const Mesh& rMesh) {
    const std::size_t nblocks = rMesh.NumCellBlocks();
    const std::vector<std::int64_t> bases = detail::block_bases(rMesh);
    std::vector<SplitGroup> groups;
    for (const std::string& name : rMesh.RegionNames()) {
        const std::size_t idx = rMesh.FindRegion(name, RegionKind::Cell);
        if (idx == Mesh::npos)
            continue;
        const Region& region = rMesh.Region(idx);
        SplitGroup group;
        group.key = name;
        split_init_group(group, nblocks);
        const std::int64_t* entries = region.Entries();
        const std::size_t n = region.NumEntries();
        for (std::size_t e = 0; e < n; ++e) {
            const auto [b, row] = detail::global_to_block_row(bases, entries[e]);
            if (b != static_cast<std::size_t>(-1))
                group.kept[b].push_back(row);
        }
        groups.push_back(std::move(group));
    }
    return groups;
}

bool split_is_integer(DType dt) {
    switch (dt) {
        case DType::Int8:
        case DType::Int16:
        case DType::Int32:
        case DType::Int64:
        case DType::UInt8:
        case DType::UInt16:
        case DType::UInt32:
        case DType::UInt64:
            return true;
        default:
            return false;
    }
}

// The integer cell_data name to split on: `rTagName` if usable, else the first
// integer cell_data covering every block. Throws if none is found.
std::string split_resolve_tag(const Mesh& rMesh, const std::string& rTagName) {
    const std::size_t nblocks = rMesh.NumCellBlocks();
    auto usable = [&](const std::string& name) {
        if (!rMesh.HasCellData(name) || rMesh.CellDataNumBlocks(name) != nblocks)
            return false;
        std::size_t b = 0;
        for (const auto cb : rMesh.CellRange()) {
            const NDArray& a = rMesh.CellData(name, b);
            const std::size_t rows = a.Shape().empty() ? 0 : a.Shape()[0];
            if (!split_is_integer(a.Dtype()) || rows != cb.NumCells())
                return false;
            ++b;
        }
        return true;
    };
    if (!rTagName.empty()) {
        if (!usable(rTagName))
            throw std::invalid_argument("split: cell_data '" + rTagName +
                                        "' is not an integer per-cell tag on every block");
        return rTagName;
    }
    for (const std::string& name : rMesh.CellDataNames())
        if (usable(name))
            return name;
    throw std::invalid_argument("split: no integer cell_data tag found (pass an explicit name)");
}

std::vector<SplitGroup> split_by_tag(const Mesh& rMesh, const std::string& rTagName) {
    const std::string name = split_resolve_tag(rMesh, rTagName);
    const std::size_t nblocks = rMesh.NumCellBlocks();
    std::vector<SplitGroup> groups;
    std::unordered_map<std::int64_t, std::size_t> index;
    std::size_t b = 0;
    for (const auto cb : rMesh.CellRange()) {
        const NDArray& tag = rMesh.CellData(name, b);
        for (std::size_t c = 0; c < cb.NumCells(); ++c) {
            const std::int64_t v = detail::read_int(tag, c);
            auto it = index.find(v);
            std::size_t gi;
            if (it == index.end()) {
                gi = groups.size();
                index[v] = gi;
                groups.push_back({});
                groups.back().key = std::to_string(v);
                split_init_group(groups.back(), nblocks);
            } else {
                gi = it->second;
            }
            groups[gi].kept[b].push_back(static_cast<std::int64_t>(c));
        }
        ++b;
    }
    return groups;
}

}  // namespace

SplitBy split_by_from_name(const std::string& rName) {
    if (rName == "type")
        return SplitBy::Type;
    if (rName == "component")
        return SplitBy::Component;
    if (rName == "region" || rName == "tag")
        return SplitBy::Tag;
    if (rName == "regions")
        return SplitBy::Region;
    throw std::invalid_argument("split: unknown criterion '" + rName +
                                "' (expected 'type', 'region'/'tag', 'regions', or 'component')");
}

SplitResult split(const Mesh& rMesh, SplitBy by, const std::string& rTagName) {
    std::vector<SplitGroup> groups;
    switch (by) {
        case SplitBy::Type:
            groups = split_by_type(rMesh);
            break;
        case SplitBy::Component:
            groups = split_by_component(rMesh);
            break;
        case SplitBy::Tag:
            groups = split_by_tag(rMesh, rTagName);
            break;
        case SplitBy::Region:
            groups = split_by_region(rMesh);
            break;
    }

    SplitResult res;
    res.mPieces.reserve(groups.size());
    for (SplitGroup& g : groups) {
        detail::SubsetResult sub =
            detail::build_cell_subset(rMesh, g.kept, "", "", /*drop_empty_blocks=*/true, "split");
        SplitPiece piece;
        piece.mKey = std::move(g.key);
        piece.mMesh = std::move(sub.mMesh);
        piece.mPointMap = std::move(sub.mPointMap);
        piece.mCellMaps = std::move(sub.mCellMaps);
        res.mPieces.push_back(std::move(piece));
    }
    return res;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/split.cpp =====
// ===== begin src/cpp/src/operations/stats.cpp =====
#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

using detail::Vec3;

// Sum the areas of the triangle/quad facets of a (linearized) surface mesh.
double stats_surface_area(const Mesh& rSurf) {
    const NDArray& points = rSurf.Points();
    const std::size_t pdim = rSurf.PointDim();
    double area = 0.0;
    for (const auto cb : rSurf.CellRange()) {
        if (cb.IsPolyhedron())
            continue;  // a volume cell, not a facet of one
        if (cb.IsRagged()) {
            for (std::size_t i = 0; i < cb.NumCells(); ++i) {
                const std::size_t n = cb.RowSize(i);
                std::vector<Vec3> coords(n);
                for (std::size_t k = 0; k < n; ++k)
                    coords[k] = detail::read_point(points, pdim, cb.Row(i)[k]);
                area += detail::polygon_area(coords.data(), n);
            }
            continue;
        }
        const CellType ct = cell_type_from_name(cb.Type());
        const int cc = detail::cell_corner_count(ct);
        if (cell_type_dimension(ct) != 2 || (cc != 3 && cc != 4))
            continue;
        const NDArray& conn = cb.Conn();
        const std::size_t npc = cb.NodesPerCell();
        const std::size_t nc = cb.NumCells();
        std::vector<double> vals(nc);
        parallel_for(nc, [&](std::size_t i) {
            std::vector<Vec3> coords;
            detail::read_corner_coords(points, pdim, conn, i * npc, static_cast<std::size_t>(cc),
                                       coords);
            vals[i] = detail::polygon_area(coords.data(), static_cast<std::size_t>(cc));
        });
        for (double v : vals)
            area += v;
    }
    return area;
}

}  // namespace

StatsReport compute_stats(const Mesh& rMesh) {
    StatsReport rep;
    const NDArray& points = rMesh.Points();
    const std::size_t n = rMesh.NumPoints();
    const std::size_t dim = rMesh.PointDim();
    rep.mNumPoints = static_cast<std::int64_t>(n);

    // --- bounding box / centroid (chunked parallel reduction) ---------------
    if (n > 0 && dim > 0) {
        const std::size_t ddim = std::min<std::size_t>(dim, 3);
        const std::size_t grain = 4096;
        const std::size_t nchunks = (n + grain - 1) / grain;
        std::vector<std::array<double, 3>> pmin(nchunks), pmax(nchunks), psum(nchunks);
        parallel_for(
            nchunks,
            [&](std::size_t ci) {
                std::array<double, 3> lmin = {std::numeric_limits<double>::infinity(),
                                              std::numeric_limits<double>::infinity(),
                                              std::numeric_limits<double>::infinity()};
                std::array<double, 3> lmax = {-std::numeric_limits<double>::infinity(),
                                              -std::numeric_limits<double>::infinity(),
                                              -std::numeric_limits<double>::infinity()};
                std::array<double, 3> lsum = {0, 0, 0};
                const std::size_t start = ci * grain;
                const std::size_t stop = std::min(n, start + grain);
                for (std::size_t g = start; g < stop; ++g)
                    for (std::size_t d = 0; d < ddim; ++d) {
                        const double v = detail::read_double(points, g * dim + d);
                        lmin[d] = std::min(lmin[d], v);
                        lmax[d] = std::max(lmax[d], v);
                        lsum[d] += v;
                    }
                pmin[ci] = lmin;
                pmax[ci] = lmax;
                psum[ci] = lsum;
            },
            1);
        std::array<double, 3> gmin = {std::numeric_limits<double>::infinity(),
                                      std::numeric_limits<double>::infinity(),
                                      std::numeric_limits<double>::infinity()};
        std::array<double, 3> gmax = {-std::numeric_limits<double>::infinity(),
                                      -std::numeric_limits<double>::infinity(),
                                      -std::numeric_limits<double>::infinity()};
        std::array<double, 3> gsum = {0, 0, 0};
        for (std::size_t ci = 0; ci < nchunks; ++ci)
            for (std::size_t d = 0; d < 3; ++d) {
                gmin[d] = std::min(gmin[d], pmin[ci][d]);
                gmax[d] = std::max(gmax[d], pmax[ci][d]);
                gsum[d] += psum[ci][d];
            }
        for (std::size_t d = 0; d < ddim; ++d) {
            rep.mBBoxMin[d] = gmin[d];
            rep.mBBoxMax[d] = gmax[d];
            rep.mExtent[d] = gmax[d] - gmin[d];
            rep.mCentroid[d] = gsum[d] / static_cast<double>(n);
        }
    }

    // --- per-cell-type counts + areas / volumes -----------------------------
    std::unordered_map<std::string, std::size_t> type_index;
    bool any_3d = false;
    for (const auto cb : rMesh.CellRange()) {
        const std::string type(cb.Type());
        const CellType ct = cell_type_from_name(type);
        const std::size_t nc = cb.NumCells();
        rep.mNumCells += static_cast<std::int64_t>(nc);

        auto it = type_index.find(type);
        if (it == type_index.end()) {
            type_index[type] = rep.mCellTypeCounts.size();
            rep.mCellTypeCounts.emplace_back(type, static_cast<std::int64_t>(nc));
        } else {
            rep.mCellTypeCounts[it->second].second += static_cast<std::int64_t>(nc);
        }

        if (cb.IsPolyhedron()) {
            // A polyhedron block's face winding is NOT a contract -- meshio++
            // repairs it rather than requiring it (doc/polyhedra.md) -- so
            // "inverted" is not a question one can ask of such a cell: there is
            // no convention for it to violate. Orient, then take the (now
            // positive) volume. What IS meaningful is an unorientable cell,
            // which is the polyhedral analogue of degenerate and is counted as
            // such rather than silently contributing zero.
            any_3d = true;
            std::vector<double> vals(nc);
            parallel_for(nc, [&](std::size_t i) {
                detail::CellRings rings;
                std::vector<Vec3> coords;
                if (!detail::cell_rings(cb, i, points, dim, rings, coords)) {
                    vals[i] = std::nan("");
                    return;
                }
                if (detail::orient_rings(rings, coords.data()) ==
                    detail::RingOrientation::Unorientable) {
                    vals[i] = std::nan("");
                    return;
                }
                vals[i] = std::abs(detail::poly_measure(rings, coords.data()).mVolume);
            });
            std::size_t n_bad = 0;
            for (double v : vals) {
                if (std::isnan(v)) {
                    ++n_bad;
                    continue;
                }
                rep.mSignedVolume += v;
                rep.mUnsignedVolume += v;
            }
            if (n_bad > 0)
                log::warn(
                    "stats: {} polyhedron cell(s) in block '{}' are not closed orientable "
                    "surfaces; their volume is not defined and is excluded",
                    n_bad, type);
            continue;
        }
        if (cb.IsRagged()) {
            // 1-level ragged (jagged polygons): a surface, so it contributes
            // area. Before v9.16.0 such a block contributed nothing at all.
            std::vector<double> vals(nc);
            parallel_for(nc, [&](std::size_t i) {
                const std::size_t n = cb.RowSize(i);
                std::vector<Vec3> coords(n);
                for (std::size_t k = 0; k < n; ++k)
                    coords[k] = detail::read_point(points, dim, cb.Row(i)[k]);
                vals[i] = detail::polygon_area(coords.data(), n);
            });
            for (double v : vals)
                rep.mTotalArea += v;
            continue;
        }
        const int cc = detail::cell_corner_count(ct);
        const int cdim = cell_type_dimension(ct);
        if (cc <= 0)
            continue;
        const NDArray& conn = cb.Conn();
        const std::size_t npc = cb.NodesPerCell();

        if (cdim == 2 && (cc == 3 || cc == 4)) {
            std::vector<double> vals(nc);
            parallel_for(nc, [&](std::size_t i) {
                std::vector<Vec3> coords;
                detail::read_corner_coords(points, dim, conn, i * npc, static_cast<std::size_t>(cc),
                                           coords);
                vals[i] = detail::polygon_area(coords.data(), static_cast<std::size_t>(cc));
            });
            for (double v : vals)
                rep.mTotalArea += v;
        } else if (cdim == 3) {
            // Deliberately NOT oriented: `cell_faces`' rows are canonically
            // outward-wound, so the sign here genuinely measures whether the
            // CELL is inverted. Repairing the winding first would make every
            // cell positive and silently zero `mNumInverted`.
            any_3d = true;
            std::vector<double> vals(nc);
            parallel_for(nc, [&](std::size_t i) {
                detail::CellRings rings;
                std::vector<Vec3> coords;
                vals[i] = detail::cell_rings(cb, i, points, dim, rings, coords)
                              ? detail::poly_measure(rings, coords.data()).mVolume
                              : std::nan("");
            });
            for (double v : vals) {
                if (std::isnan(v))
                    continue;
                rep.mSignedVolume += v;
                rep.mUnsignedVolume += std::abs(v);
                if (v < 0.0)
                    ++rep.mNumInverted;
            }
        }
    }

    // --- boundary area of 3D cells (via the surface operation) --------------
    if (any_3d) {
        try {
            rep.mTotalArea += stats_surface_area(extract_surface(rMesh));
        } catch (...) {
            // Boundary extraction failed (unsupported cell mix) — leave 3D
            // boundary area out rather than failing the whole stats report.
        }
    }

    return rep;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/stats.cpp =====
// ===== begin src/cpp/src/operations/subdivide.cpp =====
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <stdexcept>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

constexpr const char* kSubPrefix = "meshio++: subdivide: ";
constexpr const char* kSubParentName = "subdivide:parent_cell";

/// A staged output block: either an unchanged copy of an input block (any of
/// its three storage shapes), or a freshly built polyhedron block.
struct SubOutBlock {
    std::string mType;
    std::size_t mNodesPerCell = 0;  // rectangular pass-through only
    std::vector<std::int64_t> mConn;
    std::vector<std::vector<std::int64_t>> mPolygonRows;
    std::vector<std::vector<std::vector<std::int64_t>>> mPolyhedronCells;
    bool mIsRagged = false;
    bool mIsPolyhedron = false;
};

/// Stage an input block unchanged -- the pass-through case, one branch per
/// existing storage shape. Mirrors convert_cells.cpp's own staging helper;
/// not shared with it directly, since that one is file-private there too.
SubOutBlock sub_stage_passthrough(const Mesh::CellView& rBlock) {
    SubOutBlock out;
    out.mType = std::string(rBlock.Type());
    if (rBlock.IsPolyhedron()) {
        out.mIsRagged = true;
        out.mIsPolyhedron = true;
        out.mPolyhedronCells.resize(rBlock.NumCells());
        for (std::size_t c = 0; c < rBlock.NumCells(); ++c) {
            for (std::size_t f = 0; f < rBlock.NumFaces(c); ++f) {
                const auto face = rBlock.Face(c, f);
                out.mPolyhedronCells[c].emplace_back(face.first, face.first + face.second);
            }
        }
    } else if (rBlock.IsRagged()) {
        out.mIsRagged = true;
        out.mPolygonRows.resize(rBlock.NumCells());
        for (std::size_t c = 0; c < rBlock.NumCells(); ++c) {
            const std::int64_t* row = rBlock.Row(c);
            out.mPolygonRows[c].assign(row, row + rBlock.RowSize(c));
        }
    } else {
        const NDArray& conn = rBlock.Conn();
        const std::size_t npc = rBlock.NodesPerCell();
        out.mNodesPerCell = npc;
        out.mConn.resize(rBlock.NumCells() * npc);
        for (std::size_t c = 0; c < rBlock.NumCells(); ++c)
            for (std::size_t k = 0; k < npc; ++k)
                out.mConn[c * npc + k] = detail::read_int(conn, c * npc + k);
    }
    return out;
}

/// Add a staged block to `rOut`.
void sub_emit_block(Mesh& rOut, SubOutBlock& rBlock) {
    if (rBlock.mIsPolyhedron) {
        rOut.AddPolyhedronBlock(rBlock.mType, std::move(rBlock.mPolyhedronCells));
    } else if (rBlock.mIsRagged) {
        rOut.AddPolygonBlock(rBlock.mType, std::move(rBlock.mPolygonRows));
    } else {
        const std::size_t npc = rBlock.mNodesPerCell;
        const std::size_t ncells = npc == 0 ? 0 : rBlock.mConn.size() / npc;
        NDArray conn = NDArray::Uninit(DType::Int64, {ncells, npc});
        std::int64_t* dst = conn.As<std::int64_t>();
        for (std::size_t i = 0; i < rBlock.mConn.size(); ++i)
            dst[i] = rBlock.mConn[i];
        rOut.AddCellBlock(rBlock.mType, std::move(conn));
    }
}

/// Whether a block can be polyhedrally subdivided: a 3D type with a
/// `cell_faces` row (reduces to corners for any quadratic variant), or an
/// existing polyhedron block. 2D/1D blocks and the 3D Lagrange family (no
/// `cell_faces` row) pass through unchanged instead.
bool sub_eligible(const Mesh::CellView& rBlock) {
    if (rBlock.IsPolyhedron())
        return true;
    if (rBlock.IsRagged())
        return false;  // a ragged (polygon) block has no volume to subdivide
    const CellType t = cell_type_from_name(rBlock.Type());
    if (cell_type_dimension(t) != 3)
        return false;
    return !detail::cell_faces(t).empty();
}

}  // namespace

SubdivideResult subdivide(const Mesh& rMesh, const SubdivideOptions& rOptions) {
    const std::size_t nblocks = rMesh.NumCellBlocks();
    const std::size_t num_points = rMesh.NumPoints();
    const NDArray& points = rMesh.Points();
    const std::size_t pdim = rMesh.PointDim();

    // Every new point's coordinates are the plain average of a list of
    // existing node ids -- resolved in one batch pass after the main loop,
    // exactly convert_cells.cpp's own polyhedron-branch convention.
    std::vector<std::vector<std::int64_t>> new_point_src;

    std::vector<SubOutBlock> staged;
    staged.reserve(nblocks);
    std::vector<std::vector<std::int64_t>> first_child(nblocks);
    std::vector<std::vector<std::int64_t>> parent_of_child(nblocks);

    detail::CellRings rings;
    std::vector<detail::Vec3> coords;

    for (std::size_t b = 0; b < nblocks; ++b) {
        const auto cb = rMesh.Cells(b);
        const std::size_t ncells = cb.NumCells();
        std::vector<std::int64_t>& firsts = first_child[b];
        std::vector<std::int64_t>& parents = parent_of_child[b];
        firsts.resize(ncells);

        if (!sub_eligible(cb)) {
            staged.push_back(sub_stage_passthrough(cb));
            for (std::size_t c = 0; c < ncells; ++c) {
                firsts[c] = static_cast<std::int64_t>(c);
                parents.push_back(static_cast<std::int64_t>(c));
            }
            continue;
        }

        SubOutBlock out;
        out.mType = "polyhedron";
        out.mIsRagged = true;
        out.mIsPolyhedron = true;
        out.mPolyhedronCells.reserve(ncells);

        for (std::size_t c = 0; c < ncells; ++c) {
            firsts[c] = static_cast<std::int64_t>(out.mPolyhedronCells.size());
            if (!detail::cell_rings(cb, c, points, pdim, rings, coords))
                continue;  // no face topology at all: contributes nothing
            if (detail::orient_rings(rings, coords.data()) == detail::RingOrientation::Unorientable)
                throw std::invalid_argument(
                    std::string(kSubPrefix) + "cannot subdivide cell " + std::to_string(c) +
                    " of block '" + std::string(cb.Type()) +
                    "': its faces are not a closed orientable surface, so it bounds no volume");

            // One new interior point per cell: the plain average of the
            // cell's own corner nodes -- deliberately not poly_measure()'s
            // volume centroid, a different point. See the file docs.
            const std::int64_t apex = static_cast<std::int64_t>(num_points + new_point_src.size());
            new_point_src.push_back(rings.mNodes);

            for (std::size_t f = 0; f < rings.NumFaces(); ++f) {
                const std::uint32_t* ring = rings.Face(f);
                const std::size_t m = rings.FaceSize(f);

                std::vector<std::vector<std::int64_t>> child;
                child.reserve(1 + m);
                // The original face, unchanged (same global ids, same
                // winding), so a neighbouring cell across it still sees the
                // identical face -- this is what keeps the result conforming.
                std::vector<std::int64_t> face_nodes(m);
                for (std::size_t k = 0; k < m; ++k)
                    face_nodes[k] = rings.mNodes[ring[k]];
                child.push_back(std::move(face_nodes));
                // One new triangle per face edge, back to the apex.
                for (std::size_t k = 0; k < m; ++k) {
                    const std::int64_t a = rings.mNodes[ring[k]];
                    const std::int64_t nb = rings.mNodes[ring[(k + 1) % m]];
                    child.push_back({apex, a, nb});
                }
                out.mPolyhedronCells.push_back(std::move(child));
                parents.push_back(static_cast<std::int64_t>(c));
            }
        }
        staged.push_back(std::move(out));
    }

    Mesh out;
    if (new_point_src.empty()) {
        out.AssignPoints(detail::data_owned_copy(points));
    } else {
        const std::size_t dim = pdim;
        NDArray np = NDArray::Uninit(points.Dtype(), {num_points + new_point_src.size(), dim});
        std::memcpy(np.Data(), points.Data(), points.Nbytes());
        parallel_for_bw(new_point_src.size(), [&](std::size_t i) {
            const std::vector<std::int64_t>& src = new_point_src[i];
            for (std::size_t d = 0; d < dim; ++d) {
                double sum = 0.0;
                for (std::int64_t nid : src)
                    sum += detail::read_double(points, static_cast<std::size_t>(nid) * dim + d);
                detail::write_double(np, (num_points + i) * dim + d,
                                     sum / static_cast<double>(src.size()));
            }
        });
        out.AssignPoints(std::move(np));
    }

    for (SubOutBlock& block : staged)
        sub_emit_block(out, block);

    // point_data: originals copied verbatim; new (apex) points get the mean
    // of their source nodes' values, the same convention as coordinates.
    for (const std::string& name : rMesh.PointDataNames()) {
        const NDArray& a = rMesh.PointData(name);
        if (detail::rows(a) != num_points || new_point_src.empty()) {
            out.AddPointData(name, detail::data_owned_copy(a));
            continue;
        }
        const std::size_t ncomp = num_points == 0 ? 0 : a.Size() / num_points;
        std::vector<std::size_t> shape = a.Shape();
        shape[0] = num_points + new_point_src.size();
        NDArray b = NDArray::Uninit(a.Dtype(), std::move(shape));
        std::memcpy(b.Data(), a.Data(), a.Nbytes());
        parallel_for_bw(new_point_src.size(), [&](std::size_t i) {
            const std::vector<std::int64_t>& src = new_point_src[i];
            for (std::size_t k = 0; k < ncomp; ++k) {
                double sum = 0.0;
                for (std::int64_t nid : src)
                    sum += detail::read_double(a, static_cast<std::size_t>(nid) * ncomp + k);
                detail::write_double(b, (num_points + i) * ncomp + k,
                                     sum / static_cast<double>(src.size()));
            }
        });
        out.AddPointData(name, std::move(b));
    }

    // cell_data: replicate each parent's row to its children, by raw byte copy
    // (dtype-agnostic, no precision loss) -- convert_cells.cpp's own pattern
    // for the identical "each child inherits its parent's row" shape. An
    // array whose block count does not match the mesh is not per-cell data,
    // so it is copied verbatim rather than mangled.
    for (const std::string& name : rMesh.CellDataNames()) {
        const std::size_t ndata = rMesh.CellDataNumBlocks(name);
        std::vector<NDArray> blocks;
        blocks.reserve(ndata);
        for (std::size_t b = 0; b < ndata; ++b) {
            const NDArray& src = rMesh.CellData(name, b);
            const std::size_t in_rows = detail::rows(src);
            if (ndata != nblocks || in_rows == 0 || parent_of_child[b].empty()) {
                blocks.push_back(detail::data_owned_copy(src));
                continue;
            }
            const std::vector<std::int64_t>& parents = parent_of_child[b];
            std::vector<std::size_t> shape = src.Shape();
            shape[0] = parents.size();
            const std::size_t row_bytes = src.Nbytes() / in_rows;
            NDArray dst = NDArray::Uninit(src.Dtype(), std::move(shape));
            const std::byte* p_src = src.Data();
            std::byte* p_dst = dst.Data();
            parallel_for_bw(parents.size(), [&](std::size_t i) {
                std::memcpy(p_dst + i * row_bytes,
                            p_src + static_cast<std::size_t>(parents[i]) * row_bytes, row_bytes);
            });
            blocks.push_back(std::move(dst));
        }
        out.AddCellData(name, std::move(blocks));
    }
    for (const std::string& name : rMesh.FieldDataNames())
        out.AddFieldData(name, detail::data_owned_copy(rMesh.FieldData(name)));

    if (rOptions.mRecordParentIds) {
        std::vector<NDArray> blocks;
        blocks.reserve(nblocks);
        for (const std::vector<std::int64_t>& parents : parent_of_child) {
            NDArray dst(DType::Int64, {parents.size()});
            std::int64_t* p = dst.As<std::int64_t>();
            for (std::size_t i = 0; i < parents.size(); ++i)
                p[i] = parents[i];
            blocks.push_back(std::move(dst));
        }
        out.AddCellData(kSubParentName, std::move(blocks));
    }

    SubdivideResult res;
    res.mMesh = std::move(out);
    res.mCellMaps.reserve(nblocks);
    for (std::vector<std::int64_t>& firsts : first_child) {
        NDArray m(DType::Int64, {firsts.size()});
        std::int64_t* p = m.As<std::int64_t>();
        for (std::size_t i = 0; i < firsts.size(); ++i)
            p[i] = firsts[i];
        res.mCellMaps.push_back(std::move(m));
    }

    detail::RegionRemap rmap;
    rmap.mCellMapKind = detail::CellMapKind::FirstChild;
    rmap.pCellMaps = &res.mCellMaps;
    rmap.mOpName = "subdivide";
    detail::remap_regions(rMesh, res.mMesh, rmap);

    return res;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/subdivide.cpp =====
// ===== begin src/cpp/src/operations/surface.cpp =====
#include <algorithm>
#include <array>
#include <cstdint>
#include <cstring>
#include <functional>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

// --- shared facet abstraction -----------------------------------------------

// Which kind of boundary facet we extract.
enum class SurfaceMode { Face, Edge };

// One facet of a cell, corners-first: unifies CellFaceDef (3D) and CellEdgeDef
// (2D) into a single shape so the two-phase extractor is dimension-agnostic.
struct SurfaceFacetDef {
    CellType mType;                      // output facet type
    std::uint8_t mNumCorners;            // leading entries of mNodes
    std::uint8_t mNumNodes;              // full node count of the facet
    std::array<std::uint8_t, 9> mNodes;  // local node indices, corners first
};

// The facets of a cell type for the given mode (empty if unsupported).
std::vector<SurfaceFacetDef> surface_facets_for(CellType type, SurfaceMode mode) {
    std::vector<SurfaceFacetDef> out;
    if (mode == SurfaceMode::Face) {
        for (const detail::CellFaceDef& fd : detail::cell_faces(type))
            out.push_back({fd.mFaceType, fd.mNumCorners, fd.mNumNodes, fd.mNodes});
    } else {
        for (const detail::CellEdgeDef& ed : detail::cell_edges(type)) {
            std::array<std::uint8_t, 9> nodes = {};
            nodes[0] = ed.mNodes[0];
            nodes[1] = ed.mNodes[1];
            nodes[2] = ed.mNodes[2];
            out.push_back({ed.mEdgeType, ed.mNumCorners, ed.mNumNodes, nodes});
        }
    }
    return out;
}

bool surface_mode_supported(CellType type, SurfaceMode mode) {
    return mode == SurfaceMode::Face ? detail::skin_supported(type)
                                     : detail::surface_edge_supported(type);
}

// Effective topological dimension for mode selection (polyhedron counts as 3).
int surface_effective_dim(const Mesh::CellView& rBlock) {
    if (rBlock.IsPolyhedron())
        return 3;
    return cell_type_dimension(cell_type_from_name(rBlock.Type()));
}

// A supported 3D block is a non-ragged volume block with a known face table.
bool surface_skin_block_supported(CellType type, bool is_ragged) {
    return cell_type_dimension(type) == 3 && !is_ragged && detail::skin_supported(type);
}

// --- facet key + hash -------------------------------------------------------
//
// detail::FacetKey rather than the fixed array<int64_t,4> this used before
// v9.16.0: a polyhedron's face can have any number of corners. It keeps a
// 4-entry inline fast path, so a triangle or quad still costs no allocation and
// the rectangular path is unchanged. Sharing ONE key type across both is what
// lets a hexahedron and a polyhedron that meet on a face cancel each other out
// -- with two key types they would each report that face as boundary.

using SurfaceFacetKey = detail::FacetKey;
using SurfaceFacetKeyHash = detail::FacetKeyHash;

SurfaceFacetKey surface_facet_key(const NDArray& rConn, std::size_t rowOffset,
                                  const SurfaceFacetDef& rFacet) {
    std::array<std::int64_t, 4> ids{};
    for (std::uint8_t k = 0; k < rFacet.mNumCorners; ++k)
        ids[k] = detail::read_int(rConn, rowOffset + rFacet.mNodes[k]);
    return SurfaceFacetKey(ids.data(), rFacet.mNumCorners);
}

// --- canonical output buckets -----------------------------------------------

// Face mode: triangle, triangle6, quad, quad8, quad9 (matches legacy skin).
// Edge mode: line, line3.
std::size_t surface_num_out_types(SurfaceMode mode) {
    return mode == SurfaceMode::Face ? 5 : 2;
}

std::size_t surface_out_type_index(SurfaceMode mode, CellType type) {
    if (mode == SurfaceMode::Face) {
        switch (type) {
            case CellType::Triangle:
                return 0;
            case CellType::Triangle6:
                return 1;
            case CellType::Quad:
                return 2;
            case CellType::Quad8:
                return 3;
            default:  // Quad9
                return 4;
        }
    }
    return type == CellType::Line ? 0 : 1;  // Line / Line3
}

const char* surface_out_type_name(SurfaceMode mode, std::size_t index) {
    static const char* face_names[5] = {"triangle", "triangle6", "quad", "quad8", "quad9"};
    static const char* edge_names[2] = {"line", "line3"};
    return mode == SurfaceMode::Face ? face_names[index] : edge_names[index];
}

std::size_t surface_out_type_nodes(SurfaceMode mode, std::size_t index) {
    static const std::size_t face_counts[5] = {3, 6, 4, 8, 9};
    static const std::size_t edge_counts[2] = {2, 3};
    return mode == SurfaceMode::Face ? face_counts[index] : edge_counts[index];
}

// --- per-block enumeration descriptor ---------------------------------------

struct SurfaceBlockDesc {
    const NDArray* mpConn = nullptr;  // rectangular blocks only
    std::size_t mNpc = 0;
    std::size_t mNumCells = 0;
    std::vector<SurfaceFacetDef> mFacets;  // rectangular blocks only
    std::size_t mFacetsPerCell = 0;        // rectangular blocks only
    std::size_t mFirstFacet = 0;           // offset into the flat record buffer
    std::int64_t mGlobalCellBase = 0;      // input-cell index of this block's cell 0
    // Polyhedron blocks: faces per cell vary, so the flat record offsets are
    // tabulated instead of computed as cell * mFacetsPerCell.
    bool mPolyhedron = false;
    std::size_t mBlock = 0;               // index into the mesh's cell blocks
    std::vector<std::size_t> mFaceStart;  // mNumCells + 1 record offsets
};

// One facet occurrence recorded in phase 1 (keys built in parallel).
struct SurfaceFacetRecord {
    SurfaceFacetKey mKey;
    std::uint32_t mDesc;
    std::uint32_t mCell;
    std::uint32_t mSlot;
    std::int64_t mParent;
};

}  // namespace

namespace detail {

// The shared core: extract boundary facets of the chosen mode.
//  - forceFaceMode true  => volume-only (extract_skin), honoring `linearize`.
//  - forceFaceMode false => auto (extract_surface): faces if any volume cell
//    exists, else edges.
Mesh surface_extract(const Mesh& rMesh, bool forceFaceMode, bool linearize, bool recordParentIds,
                     const char* pOpName) {
    // --- select the mode ---
    SurfaceMode mode = SurfaceMode::Face;
    if (!forceFaceMode) {
        int max_dim = -1;
        for (const auto cb : rMesh.CellRange())
            max_dim = std::max(max_dim, surface_effective_dim(cb));
        if (max_dim == 3)
            mode = SurfaceMode::Face;
        else if (max_dim == 2)
            mode = SurfaceMode::Edge;
        else
            throw std::invalid_argument(std::string(pOpName) +
                                        ": mesh contains no supported 2D or 3D cell block");
    }

    // --- pre-scan: warn per unsupported same-dimension block, require one ---
    // Face mode mirrors the legacy skin pre-scan (polyhedron counts as volume);
    // the wording ("volume"/"3D volume") is kept byte-identical to the old
    // extract_skin messages so its callers/tests are unaffected.
    const char* noun = mode == SurfaceMode::Face ? "volume" : "surface";
    const int scan_dim = mode == SurfaceMode::Face ? 3 : 2;
    bool any_supported = false;
    for (const auto cb : rMesh.CellRange()) {
        const CellType ct = cell_type_from_name(cb.Type());
        const bool same_dim = mode == SurfaceMode::Face
                                  ? (cell_type_dimension(ct) == 3 || cb.IsPolyhedron())
                                  : (cell_type_dimension(ct) == 2 && !cb.IsPolyhedron());
        if (!same_dim)
            continue;
        // A polyhedron block carries its own faces, so it is supported by
        // construction -- there is no table for it to be missing from.
        if (cb.IsPolyhedron() || (!cb.IsRagged() && surface_mode_supported(ct, mode))) {
            any_supported = true;
        } else {
            log::warn("{}: {} cell block '{}' is not supported; skipping it.", pOpName, noun,
                      cb.Type());
        }
    }
    if (!any_supported)
        throw std::invalid_argument(std::string(pOpName) + ": mesh contains no supported " +
                                    std::to_string(scan_dim) + "D " + noun + " cell block");

    // --- build per-block descriptors + a flat record buffer ---
    std::vector<SurfaceBlockDesc> descs;
    std::size_t total_facets = 0;
    std::int64_t global_cell_base = 0;
    std::size_t block_idx = 0;
    for (const auto cb : rMesh.CellRange()) {
        const CellType ct = cell_type_from_name(cb.Type());
        const std::int64_t base = global_cell_base;
        global_cell_base += static_cast<std::int64_t>(cb.NumCells());
        ++block_idx;
        const bool same_dim = mode == SurfaceMode::Face
                                  ? (cell_type_dimension(ct) == 3 || cb.IsPolyhedron())
                                  : (cell_type_dimension(ct) == 2 && !cb.IsPolyhedron());
        if (!same_dim)
            continue;
        if (cb.IsPolyhedron()) {
            // Variable faces per cell: tabulate the record offsets instead of
            // computing them from a constant facets-per-cell.
            SurfaceBlockDesc d;
            d.mPolyhedron = true;
            d.mBlock = block_idx - 1;
            d.mNumCells = cb.NumCells();
            d.mFirstFacet = total_facets;
            d.mGlobalCellBase = base;
            d.mFaceStart.reserve(d.mNumCells + 1);
            std::size_t at = 0;
            d.mFaceStart.push_back(0);
            for (std::size_t c = 0; c < d.mNumCells; ++c) {
                at += cb.NumFaces(c);
                d.mFaceStart.push_back(at);
            }
            total_facets += at;
            descs.push_back(std::move(d));
            continue;
        }
        if (cb.IsRagged() || !surface_mode_supported(ct, mode))
            continue;
        SurfaceBlockDesc d;
        d.mpConn = &cb.Conn();
        d.mNpc = cb.NodesPerCell();
        d.mNumCells = cb.NumCells();
        d.mFacets = surface_facets_for(ct, mode);
        d.mFacetsPerCell = d.mFacets.size();
        d.mFirstFacet = total_facets;
        d.mGlobalCellBase = base;
        total_facets += d.mNumCells * d.mFacetsPerCell;
        descs.push_back(std::move(d));
    }

    // --- phase 1: build facet keys into disjoint slots (parallel-safe) ---
    std::vector<SurfaceFacetRecord> recs(total_facets);
    for (std::uint32_t di = 0; di < descs.size(); ++di) {
        const SurfaceBlockDesc& d = descs[di];
        if (d.mPolyhedron) {
            const auto cb = rMesh.Cells(d.mBlock);
            parallel_for(d.mNumCells, [&, di](std::size_t c) {
                const std::size_t nf = cb.NumFaces(c);
                for (std::size_t f = 0; f < nf; ++f) {
                    const auto face = cb.Face(c, f);
                    SurfaceFacetRecord& r = recs[d.mFirstFacet + d.mFaceStart[c] + f];
                    r.mKey = SurfaceFacetKey(face.first, face.second);
                    r.mDesc = di;
                    r.mCell = static_cast<std::uint32_t>(c);
                    r.mSlot = static_cast<std::uint32_t>(f);
                    r.mParent = d.mGlobalCellBase + static_cast<std::int64_t>(c);
                }
            });
            continue;
        }
        const NDArray& conn = *d.mpConn;
        const std::size_t npc = d.mNpc;
        const std::size_t fpc = d.mFacetsPerCell;
        const std::size_t n = d.mNumCells * fpc;
        parallel_for(n, [&, di](std::size_t j) {
            const std::size_t cell = j / fpc;
            const std::size_t slot = j % fpc;
            SurfaceFacetRecord& r = recs[d.mFirstFacet + j];
            r.mKey = surface_facet_key(conn, cell * npc, d.mFacets[slot]);
            r.mDesc = di;
            r.mCell = static_cast<std::uint32_t>(cell);
            r.mSlot = static_cast<std::uint32_t>(slot);
            r.mParent = d.mGlobalCellBase + static_cast<std::int64_t>(cell);
        });
    }

    // --- phase 2, pass A: count key occurrences (serial → deterministic) ---
    std::unordered_map<SurfaceFacetKey, std::uint32_t, SurfaceFacetKeyHash> face_count;
    face_count.reserve(total_facets * 2);
    for (const SurfaceFacetRecord& r : recs)
        ++face_count[r.mKey];

    // --- phase 2, pass B: emit boundary facets (count == 1) in stored order ---
    const std::size_t num_out = surface_num_out_types(mode);
    std::vector<std::vector<std::int64_t>> out_conn(num_out);
    std::vector<std::vector<std::int64_t>> out_parent(num_out);
    // A polyhedral face may be an n-gon, which no fixed-width bucket can hold;
    // those go to a ragged `polygon` block emitted alongside the fixed ones.
    std::vector<std::vector<std::int64_t>> poly_rows;
    std::vector<std::int64_t> poly_parent;
    for (const SurfaceFacetRecord& r : recs) {
        if (face_count[r.mKey] != 1)
            continue;
        const SurfaceBlockDesc& d = descs[r.mDesc];
        if (d.mPolyhedron) {
            const auto cb = rMesh.Cells(d.mBlock);
            const auto face =
                cb.Face(static_cast<std::size_t>(r.mCell), static_cast<std::size_t>(r.mSlot));
            if (face.second == 3 || face.second == 4) {
                const std::size_t bucket = surface_out_type_index(
                    mode, face.second == 3 ? CellType::Triangle : CellType::Quad);
                std::vector<std::int64_t>& dst = out_conn[bucket];
                for (std::size_t k = 0; k < face.second; ++k)
                    dst.push_back(face.first[k]);
                if (recordParentIds)
                    out_parent[bucket].push_back(r.mParent);
            } else {
                poly_rows.emplace_back(face.first, face.first + face.second);
                if (recordParentIds)
                    poly_parent.push_back(r.mParent);
            }
            continue;
        }
        const NDArray& conn = *d.mpConn;
        const std::size_t row_offset = static_cast<std::size_t>(r.mCell) * d.mNpc;
        const SurfaceFacetDef& facet = d.mFacets[r.mSlot];
        const std::uint8_t n_out = linearize ? facet.mNumCorners : facet.mNumNodes;
        const CellType out_type =
            linearize ? (facet.mNumCorners == 3 ? CellType::Triangle : CellType::Quad)
                      : facet.mType;
        const std::size_t bucket = surface_out_type_index(mode, out_type);
        std::vector<std::int64_t>& dst = out_conn[bucket];
        for (std::uint8_t k = 0; k < n_out; ++k)
            dst.push_back(detail::read_int(conn, row_offset + facet.mNodes[k]));
        if (recordParentIds)
            out_parent[bucket].push_back(r.mParent);
    }

    // --- compaction: keep only referenced points, ascending original index ---
    const std::size_t num_points = rMesh.NumPoints();
    std::vector<char> used(num_points, 0);
    for (const std::vector<std::int64_t>& conn : out_conn)
        for (std::int64_t id : conn)
            used[static_cast<std::size_t>(id)] = 1;
    for (const std::vector<std::int64_t>& row : poly_rows)
        for (std::int64_t id : row)
            used[static_cast<std::size_t>(id)] = 1;
    std::vector<std::int64_t> remap(num_points, -1);
    std::size_t num_used = 0;
    for (std::size_t i = 0; i < num_points; ++i)
        if (used[i])
            remap[i] = static_cast<std::int64_t>(num_used++);

    Mesh surface;

    // Points: byte-row subset preserving the source dtype.
    {
        const NDArray& points = rMesh.Points();
        const std::size_t dim = detail::cols(points);
        const std::size_t row_bytes = dim * dtype_size(points.Dtype());
        NDArray new_points = NDArray::Uninit(points.Dtype(), {num_used, dim});
        const std::byte* src = points.Data();
        std::byte* dst = new_points.Data();
        std::size_t w = 0;
        for (std::size_t i = 0; i < num_points; ++i)
            if (used[i])
                std::memcpy(dst + (w++) * row_bytes, src + i * row_bytes, row_bytes);
        surface.AssignPoints(std::move(new_points));
    }

    // Cell blocks in canonical order, remapped connectivity; optional parent ids.
    std::vector<NDArray> parent_blocks;
    for (std::size_t t = 0; t < num_out; ++t) {
        const std::vector<std::int64_t>& conn = out_conn[t];
        if (conn.empty())
            continue;
        const std::size_t npc = surface_out_type_nodes(mode, t);
        NDArray block = NDArray::Uninit(DType::Int64, {conn.size() / npc, npc});
        std::int64_t* dst = block.As<std::int64_t>();
        for (std::size_t i = 0; i < conn.size(); ++i)
            dst[i] = remap[static_cast<std::size_t>(conn[i])];
        surface.AddCellBlock(surface_out_type_name(mode, t), std::move(block));
        if (recordParentIds) {
            const std::vector<std::int64_t>& par = out_parent[t];
            NDArray pblock = NDArray::Uninit(DType::Int64, {par.size(), 1});
            std::memcpy(pblock.Data(), par.data(), par.size() * sizeof(std::int64_t));
            parent_blocks.push_back(std::move(pblock));
        }
    }
    if (!poly_rows.empty()) {
        for (std::vector<std::int64_t>& row : poly_rows)
            for (std::int64_t& id : row)
                id = remap[static_cast<std::size_t>(id)];
        surface.AddPolygonBlock("polygon", std::move(poly_rows));
        if (recordParentIds) {
            NDArray pblock = NDArray::Uninit(DType::Int64, {poly_parent.size(), 1});
            std::memcpy(pblock.Data(), poly_parent.data(),
                        poly_parent.size() * sizeof(std::int64_t));
            parent_blocks.push_back(std::move(pblock));
        }
    }
    if (recordParentIds && !parent_blocks.empty())
        surface.AddCellData("surface:parent_cell", std::move(parent_blocks));

    // point_data: subset rows through the same remap; other data maps dropped.
    for (const std::string& name : rMesh.PointDataNames()) {
        const NDArray& a = rMesh.PointData(name);
        if (detail::rows(a) != num_points)
            continue;  // shape does not match the point table; drop
        std::vector<std::size_t> new_shape = a.Shape();
        new_shape[0] = num_used;
        const std::size_t row_bytes = num_points == 0 ? 0 : a.Nbytes() / num_points;
        NDArray b = NDArray::Uninit(a.Dtype(), std::move(new_shape));
        const std::byte* src = a.Data();
        std::byte* dst = b.Data();
        std::size_t w = 0;
        for (std::size_t i = 0; i < num_points; ++i)
            if (used[i])
                std::memcpy(dst + (w++) * row_bytes, src + i * row_bytes, row_bytes);
        surface.AddPointData(name, std::move(b));
    }

    // The extracted facets are newly created cells one dimension below the
    // input's, so no named region can be carried across. Say so rather than
    // dropping them silently; `record_parent_ids` is the escape hatch for a
    // caller that wants to rebuild a group itself.
    detail::warn_regions_dropped(rMesh, pOpName ? pOpName : "extract_surface");

    return surface;
}

}  // namespace detail

// --- public API -------------------------------------------------------------

Mesh extract_surface(const Mesh& rMesh, bool recordParentIds) {
    return detail::surface_extract(rMesh, /*forceFaceMode=*/false, /*linearize=*/false,
                                   recordParentIds, "extract_surface");
}

bool has_surface_extractable_cells(const Mesh& rMesh) {
    int max_dim = -1;
    for (const auto cb : rMesh.CellRange())
        max_dim = std::max(max_dim, surface_effective_dim(cb));
    const SurfaceMode mode =
        max_dim == 3 ? SurfaceMode::Face : (max_dim == 2 ? SurfaceMode::Edge : SurfaceMode::Face);
    if (max_dim != 2 && max_dim != 3)
        return false;
    for (const auto cb : rMesh.CellRange()) {
        const CellType ct = cell_type_from_name(cb.Type());
        if (!cb.IsRagged() && !cb.IsPolyhedron() && surface_mode_supported(ct, mode))
            return true;
    }
    return false;
}

Mesh extract_skin(const Mesh& rMesh, bool linearize) {
    return detail::surface_extract(rMesh, /*forceFaceMode=*/true, linearize,
                                   /*recordParentIds=*/false, "extract_skin");
}

bool has_skinnable_cells(const Mesh& rMesh) {
    // A polyhedron block carries its own faces, so it is supported by
    // construction -- there is no table for it to be missing from, the same
    // exception `surface_extract`'s own pre-scan makes. This was missed here
    // until v10.3.0: `surface_skin_block_supported` excludes every ragged
    // block including polyhedra, so a mesh with ONLY a polyhedron block (e.g.
    // `subdivide`'s output) reported false and every `has_skinnable_cells`
    // consumer (convertSurfaceOps/convert_surface, and the `skin=true`
    // default on the STL/PLY/SVG/TikZ writers) silently fell back to its
    // unskinned path instead of actually skinning it.
    for (const auto cb : rMesh.CellRange()) {
        if (cb.IsPolyhedron() ||
            surface_skin_block_supported(cell_type_from_name(cb.Type()), cb.IsRagged()))
            return true;
    }
    return false;
}

// Declared in operations/surface.hpp; see there for the rationale. Arrays
// whose block layout does not match the mesh are skipped rather than guessed
// at, matching `_viewer._flatten_cell_data` on the Python side.
void gather_cell_data_onto_surface(const Mesh& rSource, Mesh& rSurface) {
    constexpr const char* kParent = "surface:parent_cell";
    if (!rSurface.HasCellData(kParent))
        return;

    const std::size_t n_src_blocks = rSource.NumCellBlocks();
    const std::size_t n_out_blocks = rSurface.NumCellBlocks();

    // Offset of each source block in the global cell numbering, which is what
    // `surface:parent_cell` indexes.
    std::vector<std::size_t> base(n_src_blocks + 1, 0);
    for (std::size_t b = 0; b < n_src_blocks; ++b)
        base[b + 1] = base[b] + rSource.Cells(b).NumCells();
    const std::size_t n_src_cells = base[n_src_blocks];

    for (const auto& name : rSource.CellDataNames()) {
        if (rSource.CellDataNumBlocks(name) != n_src_blocks)
            continue;

        // Flatten the per-block arrays into one buffer indexed by global cell
        // id, requiring a consistent dtype and component count.
        const NDArray& first = rSource.CellData(name, 0);
        const DType dt = first.Dtype();
        const std::size_t item = dtype_size(dt);
        const std::size_t comps = first.Size() / std::max<std::size_t>(1, first.Shape()[0]);
        const std::size_t row = comps * item;

        std::vector<std::byte> flat(n_src_cells * row);
        bool usable = true;
        for (std::size_t b = 0; b < n_src_blocks && usable; ++b) {
            const NDArray& a = rSource.CellData(name, b);
            const std::size_t n = rSource.Cells(b).NumCells();
            usable =
                a.Dtype() == dt && !a.Shape().empty() && a.Shape()[0] == n && a.Size() == n * comps;
            if (usable && n)
                std::memcpy(flat.data() + base[b] * row, a.Data(), n * row);
        }
        if (!usable)
            continue;

        // Gather one output array per boundary block, by owning cell.
        std::vector<NDArray> blocks;
        blocks.reserve(n_out_blocks);
        for (std::size_t b = 0; b < n_out_blocks; ++b) {
            const NDArray& parents = rSurface.CellData(kParent, b);
            const std::size_t n = parents.Size();
            std::vector<std::size_t> shape{n};
            if (comps > 1)
                shape.push_back(comps);
            NDArray out = NDArray::Uninit(dt, shape);
            const auto* pIds = reinterpret_cast<const std::int64_t*>(parents.Data());
            for (std::size_t i = 0; i < n; ++i) {
                const auto id = static_cast<std::size_t>(pIds[i]);
                if (id < n_src_cells)
                    std::memcpy(out.Data() + i * row, flat.data() + id * row, row);
                else
                    std::memset(out.Data() + i * row, 0, row);
            }
            blocks.push_back(std::move(out));
        }
        rSurface.AddCellData(name, std::move(blocks));
    }
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/surface.cpp =====
// ===== begin src/cpp/src/operations/transform.cpp =====
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

// A deep copy of an NDArray that always owns its buffer (the source may be a
// view over foreign memory, e.g. numpy memory on the write path).
NDArray transform_owned_copy(const NDArray& rArr) {
    NDArray c = rArr;
    c.MakeOwned();
    return c;
}

// Determinant of the 3x3 linear block of a row-major 4x4 matrix.
double transform_linear_det(const std::array<double, 16>& rM) {
    const double a = rM[0], b = rM[1], c = rM[2];
    const double d = rM[4], e = rM[5], f = rM[6];
    const double g = rM[8], h = rM[9], i = rM[10];
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

// Multiply the row-major 4x4 `rA` by `rB` (result = A * B).
std::array<double, 16> transform_matmul(const std::array<double, 16>& rA,
                                        const std::array<double, 16>& rB) {
    std::array<double, 16> out = {};
    for (std::size_t r = 0; r < 4; ++r)
        for (std::size_t c = 0; c < 4; ++c) {
            double s = 0.0;
            for (std::size_t k = 0; k < 4; ++k)
                s += rA[r * 4 + k] * rB[k * 4 + c];
            out[r * 4 + c] = s;
        }
    return out;
}

// Transform the point coordinates into a fresh array of the same dtype.
NDArray transform_apply_points(const NDArray& rPoints, std::size_t n, std::size_t dim,
                               const std::array<double, 16>& rM) {
    NDArray out = NDArray::Uninit(rPoints.Dtype(), {n, dim});
    if (n == 0 || dim == 0)
        return out;
    detail::dispatch_dtype(rPoints.Dtype(), [&]<class T>() {
        const T* src = rPoints.As<T>();
        T* dst = out.As<T>();
        parallel_for_bw(n, [&](std::size_t i) {
            const std::size_t base = i * dim;
            const double x = dim > 0 ? static_cast<double>(src[base + 0]) : 0.0;
            const double y = dim > 1 ? static_cast<double>(src[base + 1]) : 0.0;
            const double z = dim > 2 ? static_cast<double>(src[base + 2]) : 0.0;
            const double nx = rM[0] * x + rM[1] * y + rM[2] * z + rM[3];
            const double ny = rM[4] * x + rM[5] * y + rM[6] * z + rM[7];
            const double nz = rM[8] * x + rM[9] * y + rM[10] * z + rM[11];
            if (dim > 0)
                dst[base + 0] = static_cast<T>(nx);
            if (dim > 1)
                dst[base + 1] = static_cast<T>(ny);
            if (dim > 2)
                dst[base + 2] = static_cast<T>(nz);
        });
    });
    return out;
}

// Rotate vector (cols == 3) or tensor (cols == 9, row-major 3x3) rows of a
// float point_data array by the 3x3 linear block `rR` (v' = R v, A' = R A R^T).
// Returns a fresh array of the same dtype. Only Float32/Float64 arrays qualify.
NDArray transform_rotate_point_data(const NDArray& rArr, std::size_t n, std::size_t cols,
                                    const std::array<double, 9>& rR) {
    NDArray out = transform_owned_copy(rArr);
    detail::dispatch_dtype(rArr.Dtype(), [&]<class T>() {
        T* p = out.As<T>();
        if (cols == 3) {
            parallel_for_bw(n, [&](std::size_t i) {
                const std::size_t b = i * 3;
                const double v0 = static_cast<double>(p[b + 0]);
                const double v1 = static_cast<double>(p[b + 1]);
                const double v2 = static_cast<double>(p[b + 2]);
                p[b + 0] = static_cast<T>(rR[0] * v0 + rR[1] * v1 + rR[2] * v2);
                p[b + 1] = static_cast<T>(rR[3] * v0 + rR[4] * v1 + rR[5] * v2);
                p[b + 2] = static_cast<T>(rR[6] * v0 + rR[7] * v1 + rR[8] * v2);
            });
        } else {  // cols == 9 : A' = R A R^T
            parallel_for_bw(n, [&](std::size_t i) {
                const std::size_t b = i * 9;
                double a[9];
                for (std::size_t k = 0; k < 9; ++k)
                    a[k] = static_cast<double>(p[b + k]);
                // tmp = R * A
                double tmp[9];
                for (std::size_t r = 0; r < 3; ++r)
                    for (std::size_t c = 0; c < 3; ++c)
                        tmp[r * 3 + c] = rR[r * 3 + 0] * a[0 * 3 + c] +
                                         rR[r * 3 + 1] * a[1 * 3 + c] +
                                         rR[r * 3 + 2] * a[2 * 3 + c];
                // out = tmp * R^T
                for (std::size_t r = 0; r < 3; ++r)
                    for (std::size_t c = 0; c < 3; ++c)
                        p[b + r * 3 + c] = static_cast<T>(tmp[r * 3 + 0] * rR[c * 3 + 0] +
                                                          tmp[r * 3 + 1] * rR[c * 3 + 1] +
                                                          tmp[r * 3 + 2] * rR[c * 3 + 2]);
            });
        }
    });
    return out;
}

bool transform_is_float(DType dt) {
    return dt == DType::Float32 || dt == DType::Float64;
}

}  // namespace

AffineTransform transform_translation(double dx, double dy, double dz) {
    AffineTransform t;
    t.mMatrix[3] = dx;
    t.mMatrix[7] = dy;
    t.mMatrix[11] = dz;
    return t;
}

AffineTransform transform_scale(double sx, double sy, double sz) {
    AffineTransform t;
    t.mMatrix[0] = sx;
    t.mMatrix[5] = sy;
    t.mMatrix[10] = sz;
    return t;
}

AffineTransform transform_units(double factor) {
    return transform_scale(factor, factor, factor);
}

AffineTransform transform_rotation(double ax, double ay, double az, double angle_rad) {
    const double len = std::sqrt(ax * ax + ay * ay + az * az);
    if (len < 1e-300)
        throw std::invalid_argument("transform: rotation axis is zero-length");
    const double x = ax / len, y = ay / len, z = az / len;
    const double c = std::cos(angle_rad), s = std::sin(angle_rad), t = 1.0 - c;
    AffineTransform out;
    auto& m = out.mMatrix;
    m[0] = t * x * x + c;
    m[1] = t * x * y - s * z;
    m[2] = t * x * z + s * y;
    m[4] = t * x * y + s * z;
    m[5] = t * y * y + c;
    m[6] = t * y * z - s * x;
    m[8] = t * x * z - s * y;
    m[9] = t * y * z + s * x;
    m[10] = t * z * z + c;
    return out;
}

AffineTransform transform_from_matrix(const double* pMatrix16) {
    AffineTransform out;
    for (std::size_t i = 0; i < 16; ++i)
        out.mMatrix[i] = pMatrix16[i];
    return out;
}

AffineTransform transform_compose(const AffineTransform& rSecond, const AffineTransform& rFirst) {
    AffineTransform out;
    out.mMatrix = transform_matmul(rSecond.mMatrix, rFirst.mMatrix);
    return out;
}

Mesh transform(const Mesh& rMesh, const AffineTransform& rXform, bool rotate_vector_data) {
    const std::array<double, 16>& M = rXform.mMatrix;
    if (transform_linear_det(M) < 0.0)
        log::warn(
            "transform: orientation-reversing (negative determinant); cell orientation "
            "may be flipped");

    Mesh out;

    // Points (transformed, dtype preserved).
    const std::size_t n = rMesh.NumPoints();
    const std::size_t dim = rMesh.PointDim();
    out.AssignPoints(transform_apply_points(rMesh.Points(), n, dim, M));

    // Cells (clone; rectangular / polygon / polyhedron).
    for (const auto cb : rMesh.CellRange()) {
        if (cb.IsPolyhedron()) {
            std::vector<std::vector<std::vector<std::int64_t>>> cells(cb.NumCells());
            for (std::size_t c = 0; c < cb.NumCells(); ++c) {
                cells[c].resize(cb.NumFaces(c));
                for (std::size_t f = 0; f < cb.NumFaces(c); ++f) {
                    auto face = cb.Face(c, f);
                    cells[c][f].assign(face.first, face.first + face.second);
                }
            }
            out.AddPolyhedronBlock(std::string(cb.Type()), std::move(cells));
        } else if (cb.IsRagged()) {
            std::vector<std::vector<std::int64_t>> rows(cb.NumCells());
            for (std::size_t c = 0; c < cb.NumCells(); ++c)
                rows[c].assign(cb.Row(c), cb.Row(c) + cb.RowSize(c));
            out.AddPolygonBlock(std::string(cb.Type()), std::move(rows));
        } else {
            out.AddCellBlock(std::string(cb.Type()), transform_owned_copy(cb.Conn()));
        }
    }

    // Point data (optionally rotate vector/tensor float arrays).
    const std::array<double, 9> R = {M[0], M[1], M[2], M[4], M[5], M[6], M[8], M[9], M[10]};
    for (const std::string& name : rMesh.PointDataNames()) {
        const NDArray& a = rMesh.PointData(name);
        const std::size_t cols = n > 0 ? a.Size() / n : 0;
        if (rotate_vector_data && transform_is_float(a.Dtype()) && n > 0 &&
            (cols == 3 || cols == 9))
            out.AddPointData(name, transform_rotate_point_data(a, n, cols, R));
        else
            out.AddPointData(name, transform_owned_copy(a));
    }

    // Cell data + field data (carried through unchanged).
    for (const std::string& name : rMesh.CellDataNames()) {
        std::vector<NDArray> blocks;
        for (std::size_t b = 0; b < rMesh.CellDataNumBlocks(name); ++b)
            blocks.push_back(transform_owned_copy(rMesh.CellData(name, b)));
        out.AddCellData(name, std::move(blocks));
    }
    for (const std::string& name : rMesh.FieldDataNames())
        out.AddFieldData(name, transform_owned_copy(rMesh.FieldData(name)));

    // Named regions pass through verbatim: a transform moves coordinates and
    // renumbers nothing, so every point, cell and facet index still names the
    // same entity.
    for (std::size_t i = 0; i < rMesh.NumRegions(); ++i)
        out.AddRegion(rMesh.Region(i));
    // Property sets ride along too: these operations preserve the mesh's shape,
    // so dropping a deck's material data here would be new lossiness. They are
    // keyed by id, not by entity index, so there is nothing to remap.
    for (std::size_t i = 0; i < rMesh.NumPropertySets(); ++i)
        out.AddPropertySet(rMesh.GetPropertySet(i));

    return out;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/transform.cpp =====
// ===== begin src/cpp/src/operations/undo_green.cpp =====
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

constexpr const char* kUgPrefix = "meshio++: undo_green: ";

// Read a required Int64 scalar cell_data array (one value per cell, covering
// every block) into a flat global-cell-order vector. Throws by name on any
// mismatch -- undo_green's fine-mesh preconditions are hard requirements,
// unlike detail::refine_read_hierarchy's warn-and-fall-back contract.
std::vector<std::int64_t> ug_read_required(const Mesh& rMesh,
                                           const std::vector<std::int64_t>& rBases,
                                           const char* pName) {
    if (!rMesh.HasCellData(pName))
        throw std::invalid_argument(
            std::string(kUgPrefix) + "the fine mesh has no '" + pName +
            "' cell_data; run refine(..., record_hierarchy=True, record_levels=True) first");
    const std::size_t nblocks = rMesh.NumCellBlocks();
    if (rMesh.CellDataNumBlocks(pName) != nblocks)
        throw std::invalid_argument(std::string(kUgPrefix) + "'" + pName +
                                    "' does not cover every cell block");
    std::vector<std::int64_t> out(static_cast<std::size_t>(detail::total_cells(rBases)));
    std::size_t bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        const std::size_t base = static_cast<std::size_t>(rBases[bi]);
        const std::size_t ncells = cb.NumCells();
        const NDArray& a = rMesh.CellData(pName, bi);
        if (detail::rows(a) != ncells || (ncells != 0 && a.Size() / ncells != 1))
            throw std::invalid_argument(std::string(kUgPrefix) + "'" + pName + "' block " +
                                        std::to_string(bi) + " is not one scalar value per cell");
        for (std::size_t c = 0; c < ncells; ++c)
            out[base + c] = detail::read_int(a, c);
        ++bi;
    }
    return out;
}

// Same shape check, but returns empty rather than throwing when `pName` is
// absent or malformed -- used for the coarse mesh's OPTIONAL refine:level,
// where absence means "never refined" (implicit level 0 for every cell).
std::vector<std::int64_t> ug_read_optional(const Mesh& rMesh,
                                           const std::vector<std::int64_t>& rBases,
                                           const char* pName) {
    if (!rMesh.HasCellData(pName))
        return {};
    const std::size_t nblocks = rMesh.NumCellBlocks();
    if (rMesh.CellDataNumBlocks(pName) != nblocks)
        return {};
    std::vector<std::int64_t> out(static_cast<std::size_t>(detail::total_cells(rBases)));
    std::size_t bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        const std::size_t base = static_cast<std::size_t>(rBases[bi]);
        const std::size_t ncells = cb.NumCells();
        const NDArray& a = rMesh.CellData(pName, bi);
        if (detail::rows(a) != ncells || (ncells != 0 && a.Size() / ncells != 1))
            return {};
        for (std::size_t c = 0; c < ncells; ++c)
            out[base + c] = detail::read_int(a, c);
        ++bi;
    }
    return out;
}

// Whether a name is one of the six reserved refine:* arrays -- always
// excluded from undo_green's output (stale hierarchy bookkeeping).
bool ug_is_reserved(const std::string& rName) {
    return rName == kRefineParentCellName || rName == kRefineLevelName ||
           rName == kRefineHangingName || rName == kRefineEntityName ||
           rName == kRefineCellIdName || rName == kRefineParentIdName;
}

// A cell's role in the output, decided once per sibling group.
enum class UgRole { Keep, AnchorSubstitute, Suppressed };

}  // namespace

UndoGreenResult undo_green(const Mesh& rCoarse, const Mesh& rFine) {
    if (rCoarse.NumPoints() > rFine.NumPoints())
        throw std::invalid_argument(
            std::string(kUgPrefix) +
            "the coarse mesh has more points than the fine mesh, so they cannot be the "
            "coarse/fine pair of one refine() call");

    const std::vector<std::int64_t> fine_bases = detail::block_bases(rFine);
    const std::vector<std::int64_t> coarse_bases = detail::block_bases(rCoarse);
    const auto total_fine = static_cast<std::size_t>(detail::total_cells(fine_bases));

    const std::vector<std::int64_t> fine_id =
        ug_read_required(rFine, fine_bases, kRefineCellIdName);
    const std::vector<std::int64_t> fine_parent =
        ug_read_required(rFine, fine_bases, kRefineParentIdName);
    const std::vector<std::int64_t> fine_level =
        ug_read_required(rFine, fine_bases, kRefineLevelName);

    // --- resolve the coarse mesh's id space: its own recorded ids if valid,
    // else the implicit global-block-major ids -- refine_attach_hierarchy's
    // own "start fresh" fallback. --------------------------------------------
    std::vector<std::int64_t> coarse_ids;
    std::int64_t coarse_id_base = 0;
    const detail::RefineHierarchyState state =
        detail::refine_read_hierarchy(rCoarse, coarse_bases, coarse_ids, coarse_id_base);
    if (state != detail::RefineHierarchyState::Valid) {
        const auto total_coarse = static_cast<std::size_t>(detail::total_cells(coarse_bases));
        coarse_ids.resize(total_coarse);
        for (std::size_t i = 0; i < total_coarse; ++i)
            coarse_ids[i] = static_cast<std::int64_t>(i);
    }
    std::unordered_map<std::int64_t, std::int64_t> id_to_coarse_row;
    id_to_coarse_row.reserve(coarse_ids.size());
    for (std::size_t i = 0; i < coarse_ids.size(); ++i)
        id_to_coarse_row[coarse_ids[i]] = static_cast<std::int64_t>(i);

    const std::vector<std::int64_t> coarse_level =
        ug_read_optional(rCoarse, coarse_bases, kRefineLevelName);
    auto coarse_level_at = [&](std::int64_t row) -> std::int64_t {
        return coarse_level.empty() ? 0 : coarse_level[static_cast<std::size_t>(row)];
    };

    // --- group fine cells by parent_id --------------------------------------
    std::unordered_map<std::int64_t, std::vector<std::int64_t>> groups_by_parent;
    for (std::size_t g = 0; g < total_fine; ++g)
        groups_by_parent[fine_parent[g]].push_back(static_cast<std::int64_t>(g));

    // --- classify every global fine cell's role; for green groups, resolve
    // the substitution source once ------------------------------------------
    std::vector<UgRole> role(total_fine, UgRole::Keep);
    std::vector<std::int64_t> group_id_of(total_fine, -1);
    std::vector<std::int64_t> group_coarse_row;  // indexed by green group id
    std::vector<std::int64_t> group_size;        // indexed by green group id
    std::int64_t next_group_id = 0;

    for (auto& entry : groups_by_parent) {
        const std::int64_t parent_id = entry.first;
        std::vector<std::int64_t>& members = entry.second;
        std::sort(members.begin(), members.end());

        if (members.size() == 1) {
            const std::int64_t g = members.front();
            if (fine_id[static_cast<std::size_t>(g)] != parent_id)
                throw std::invalid_argument(
                    std::string(kUgPrefix) +
                    "malformed hierarchy: a singleton sibling group's refine:cell_id does not "
                    "equal its refine:parent_id (cell " +
                    std::to_string(g) + ")");
            continue;  // untouched: role stays Keep
        }

        const auto it = id_to_coarse_row.find(parent_id);
        if (it == id_to_coarse_row.end())
            throw std::invalid_argument(
                std::string(kUgPrefix) + "refine:parent_id " + std::to_string(parent_id) +
                " does not resolve in the coarse mesh's id space -- these two meshes are not "
                "the coarse/fine pair of one refine() call");
        const std::int64_t coarse_row = it->second;
        const std::int64_t clevel = coarse_level_at(coarse_row);

        const std::int64_t flevel = fine_level[static_cast<std::size_t>(members.front())];
        for (std::int64_t g : members)
            if (fine_level[static_cast<std::size_t>(g)] != flevel)
                throw std::invalid_argument(
                    std::string(kUgPrefix) +
                    "malformed hierarchy: the sibling group under refine:parent_id " +
                    std::to_string(parent_id) + " does not agree on refine:level");

        if (flevel == clevel + 1)
            continue;  // red: a genuine refinement, kept unchanged (role stays Keep)

        if (flevel > clevel + 1)
            throw std::invalid_argument(
                std::string(kUgPrefix) + "the sibling group under refine:parent_id " +
                std::to_string(parent_id) + " has refine:level " + std::to_string(flevel) +
                ", more than one deeper than its coarse parent's own level (" +
                std::to_string(clevel) +
                "); undo_green only supports a single-pass (levels=1) hierarchy");

        if (flevel != clevel)
            throw std::invalid_argument(
                std::string(kUgPrefix) + "the sibling group under refine:parent_id " +
                std::to_string(parent_id) + " has refine:level " + std::to_string(flevel) +
                ", which is neither its coarse parent's own level (" + std::to_string(clevel) +
                ", green) nor one more (" + std::to_string(clevel + 1) + ", red)");

        // green: substitute the whole group with one row from the coarse mesh
        const std::int64_t gid = next_group_id++;
        group_coarse_row.push_back(coarse_row);
        group_size.push_back(static_cast<std::int64_t>(members.size()));
        role[static_cast<std::size_t>(members.front())] = UgRole::AnchorSubstitute;
        group_id_of[static_cast<std::size_t>(members.front())] = gid;
        for (std::size_t k = 1; k < members.size(); ++k) {
            role[static_cast<std::size_t>(members[static_cast<std::ptrdiff_t>(k)])] =
                UgRole::Suppressed;
            group_id_of[static_cast<std::size_t>(members[static_cast<std::ptrdiff_t>(k)])] = gid;
        }
    }

    // --- build the output mesh: fine's own block structure, unchanged types
    // and order, rows compacted/substituted -----------------------------------
    Mesh out;
    out.AssignPoints(detail::data_owned_copy(rFine.Points()));

    const std::size_t nblocks = rFine.NumCellBlocks();
    std::vector<std::size_t> out_ncells(nblocks, 0);
    {
        std::size_t bi = 0;
        for (const auto cb : rFine.CellRange()) {
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::size_t g = static_cast<std::size_t>(fine_bases[bi]) + r;
                if (role[g] != UgRole::Suppressed)
                    ++out_ncells[bi];
            }
            ++bi;
        }
    }

    std::vector<NDArray> cell_maps(nblocks);
    std::vector<NDArray> out_conn(nblocks);
    std::vector<std::int64_t> group_output_global(static_cast<std::size_t>(next_group_id), -1);
    std::vector<std::size_t> group_fine_block(static_cast<std::size_t>(next_group_id), 0);

    {
        std::size_t bi = 0;
        std::int64_t out_block_base = 0;
        for (const auto cb : rFine.CellRange()) {
            const std::size_t npc = cb.NodesPerCell();
            NDArray conn = NDArray::Uninit(DType::Int64, {out_ncells[bi], npc});
            std::int64_t* dst = conn.As<std::int64_t>();
            NDArray cmap = NDArray::Uninit(DType::Int64, {cb.NumCells()});
            std::int64_t* cm = cmap.As<std::int64_t>();

            std::size_t out_row = 0;
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::size_t g = static_cast<std::size_t>(fine_bases[bi]) + r;
                if (role[g] == UgRole::Suppressed) {
                    const std::int64_t gid = group_id_of[g];
                    cm[r] = group_output_global[static_cast<std::size_t>(gid)];
                    continue;
                }
                if (role[g] == UgRole::Keep) {
                    const NDArray& src = cb.Conn();
                    for (std::size_t k = 0; k < npc; ++k)
                        dst[out_row * npc + k] = detail::read_int(src, r * npc + k);
                } else {  // AnchorSubstitute
                    const std::int64_t gid = group_id_of[g];
                    const std::int64_t coarse_row = group_coarse_row[static_cast<std::size_t>(gid)];
                    const auto blk_row = detail::global_to_block_row(coarse_bases, coarse_row);
                    const auto ccb = rCoarse.Cells(blk_row.first);
                    const NDArray& csrc = ccb.Conn();
                    for (std::size_t k = 0; k < npc; ++k)
                        dst[out_row * npc + k] = detail::read_int(
                            csrc, static_cast<std::size_t>(blk_row.second) * npc + k);
                    group_output_global[static_cast<std::size_t>(gid)] =
                        out_block_base + static_cast<std::int64_t>(out_row);
                    group_fine_block[static_cast<std::size_t>(gid)] = bi;
                }
                cm[r] = out_block_base + static_cast<std::int64_t>(out_row);
                ++out_row;
            }

            out_conn[bi] = std::move(conn);
            cell_maps[bi] = std::move(cmap);
            out_block_base += static_cast<std::int64_t>(out_ncells[bi]);
            ++bi;
        }
    }

    {
        std::size_t bi = 0;
        for (const auto cb : rFine.CellRange()) {
            out.AddCellBlock(std::string(cb.Type()), std::move(out_conn[bi]));
            ++bi;
        }
    }

    // --- point_data / field_data: unchanged, no new or pruned points --------
    // (refine:entity / refine:hanging are POINT data, not cell_data, but are
    // just as much stale hierarchy bookkeeping as the four cell_data ones --
    // ug_is_reserved covers all six, so this loop must consult it too)
    for (const std::string& name : rFine.PointDataNames()) {
        if (ug_is_reserved(name))
            continue;
        out.AddPointData(name, detail::data_owned_copy(rFine.PointData(name)));
    }
    for (const std::string& name : rFine.FieldDataNames())
        out.AddFieldData(name, detail::data_owned_copy(rFine.FieldData(name)));

    // --- cell_data: reserved refine:* arrays dropped; everything else kept
    // (fine's own row for Keep, coarse's for AnchorSubstitute) ---------------
    for (const std::string& name : rFine.CellDataNames()) {
        if (ug_is_reserved(name))
            continue;
        if (rFine.CellDataNumBlocks(name) != nblocks) {
            log::warn(
                "{}cell_data '{}' does not have one array per fine block; dropped rather than "
                "guessed at",
                kUgPrefix, name);
            continue;
        }

        // Pre-check every green group's substitution source before touching
        // anything, so a bad array is dropped whole rather than half-built.
        bool ok = true;
        if (next_group_id > 0) {
            if (!rCoarse.HasCellData(name) ||
                rCoarse.CellDataNumBlocks(name) != rCoarse.NumCellBlocks()) {
                ok = false;
            } else {
                for (std::int64_t gid = 0; ok && gid < next_group_id; ++gid) {
                    const auto ug = static_cast<std::size_t>(gid);
                    const auto blk_row =
                        detail::global_to_block_row(coarse_bases, group_coarse_row[ug]);
                    const NDArray& fsrc = rFine.CellData(name, group_fine_block[ug]);
                    const NDArray& csrc = rCoarse.CellData(name, blk_row.first);
                    const std::size_t f_row_bytes =
                        fsrc.Nbytes() / std::max<std::size_t>(1, detail::rows(fsrc));
                    const std::size_t c_row_bytes =
                        csrc.Nbytes() / std::max<std::size_t>(1, detail::rows(csrc));
                    if (fsrc.Dtype() != csrc.Dtype() || f_row_bytes != c_row_bytes)
                        ok = false;
                }
            }
        }
        if (!ok) {
            log::warn(
                "{}cell_data '{}' cannot be honestly restored for a substituted cell (missing, "
                "incomplete or a different shape/dtype on the coarse mesh); dropped",
                kUgPrefix, name);
            continue;
        }

        std::vector<NDArray> out_blocks(nblocks);
        std::size_t bi = 0;
        for (const auto cb : rFine.CellRange()) {
            const NDArray& fsrc = rFine.CellData(name, bi);
            std::vector<std::size_t> shape = fsrc.Shape();
            shape[0] = out_ncells[bi];
            NDArray dst = NDArray::Uninit(fsrc.Dtype(), shape);
            const std::size_t row_bytes =
                fsrc.Nbytes() / std::max<std::size_t>(1, detail::rows(fsrc));
            std::byte* p_dst = dst.Data();
            const std::byte* p_fsrc = fsrc.Data();

            std::size_t out_row = 0;
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::size_t g = static_cast<std::size_t>(fine_bases[bi]) + r;
                if (role[g] == UgRole::Suppressed)
                    continue;
                if (role[g] == UgRole::Keep) {
                    std::memcpy(p_dst + out_row * row_bytes, p_fsrc + r * row_bytes, row_bytes);
                } else {  // AnchorSubstitute
                    const std::int64_t gid = group_id_of[g];
                    const auto ug = static_cast<std::size_t>(gid);
                    const auto blk_row =
                        detail::global_to_block_row(coarse_bases, group_coarse_row[ug]);
                    const NDArray& csrc = rCoarse.CellData(name, blk_row.first);
                    std::memcpy(p_dst + out_row * row_bytes,
                                csrc.Data() + static_cast<std::size_t>(blk_row.second) * row_bytes,
                                row_bytes);
                }
                ++out_row;
            }
            out_blocks[bi] = std::move(dst);
            ++bi;
        }
        out.AddCellData(name, std::move(out_blocks));
    }

    UndoGreenResult res;
    res.mMesh = std::move(out);
    res.mCellMaps = std::move(cell_maps);
    res.mNumGroupsUndone = next_group_id;
    std::int64_t removed = 0;
    for (std::int64_t sz : group_size)
        removed += sz - 1;
    res.mNumCellsRemoved = removed;

    detail::RegionRemap rmap;
    rmap.mCellMapKind = detail::CellMapKind::Direct;
    rmap.pCellMaps = &res.mCellMaps;
    rmap.mDropSideRegions = true;
    rmap.mOpName = "undo_green";
    detail::remap_regions(rFine, res.mMesh, rmap);

    return res;
}

}  // namespace meshioplusplus
